-- Frozen snapshot of Mandible schema v158, the minimum supported schema version
-- (MINIMUM_SUPPORTED_SCHEMA_VERSION in src/db-migrations.ts).
--
-- This is history, not a generated artifact. It was captured from a database
-- created by the v158 fresh-schema baseline at commit 66387abc, the last commit
-- before the v1-v158 migration chain was collapsed into src/db-baseline.ts, and
-- it is byte-for-byte what the production database's schema was at that point.
--
-- test/db-migration-convergence.test.ts migrates this fixture to head and fails
-- if the result differs from a freshly created database. Regenerating this file
-- from the current baseline would make that check vacuous: never do it. When the
-- supported floor is raised, capture a new frozen fixture at the new floor and
-- delete this one.
--
-- Statements are whitespace-normalized to one line each; the convergence test
-- compares normalized DDL, so this does not weaken the comparison.

CREATE TABLE artifact ( id TEXT PRIMARY KEY, identity_key TEXT NOT NULL, source_kind TEXT NOT NULL DEFAULT 'managed' CHECK(source_kind IN ('tracked_repo','local_only','managed','external','mixed')), title TEXT, source_project_id TEXT REFERENCES ledger_projects(id) ON DELETE RESTRICT, source_repo_id TEXT, logical_name TEXT, source_path TEXT, latest_version_id TEXT, version_count INTEGER NOT NULL DEFAULT 0, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(identity_key) );
CREATE TABLE "artifact_aliases" ( id TEXT PRIMARY KEY, artifact_id TEXT REFERENCES artifacts(id) ON DELETE SET NULL, blob_id TEXT REFERENCES artifact_blob(id) ON DELETE RESTRICT, scheme TEXT NOT NULL, alias TEXT NOT NULL, normalized_ref TEXT NOT NULL, locator_json TEXT NOT NULL DEFAULT '{}', resolution_status TEXT NOT NULL DEFAULT 'resolved' CHECK(resolution_status IN ('resolved','unresolved','ambiguous','unsupported')), source TEXT NOT NULL DEFAULT 'artifact_registry', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, CHECK ( (resolution_status = 'resolved' AND blob_id IS NOT NULL) OR (resolution_status != 'resolved' AND blob_id IS NULL) ) );
CREATE TABLE artifact_blob ( id TEXT PRIMARY KEY, algorithm TEXT NOT NULL DEFAULT 'sha256', content_hash TEXT NOT NULL, storage_uri TEXT, media_type TEXT, role TEXT, size_bytes INTEGER NOT NULL DEFAULT 0, provider_id TEXT, manifest_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', custody_mode TEXT NOT NULL DEFAULT 'managed' CHECK(custody_mode IN ('link','copy','managed','external')), availability TEXT NOT NULL DEFAULT 'unchecked' CHECK(availability IN ('present','missing','stale','unchecked','remote_only','pinned')), retention_json TEXT NOT NULL DEFAULT '{}', reference_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, UNIQUE(algorithm, content_hash) );
CREATE TABLE "artifact_drafts" ( id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifact(id) ON DELETE CASCADE, version_id TEXT NOT NULL REFERENCES artifact_version(id) ON DELETE RESTRICT, series_id TEXT REFERENCES artifact_series(id) ON DELETE SET NULL, base_version_id TEXT REFERENCES artifact_versions(id) ON DELETE SET NULL, content TEXT NOT NULL, media_type TEXT, label TEXT, note TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(artifact_id) );
CREATE TABLE "artifact_links" ( id TEXT PRIMARY KEY, artifact_id TEXT REFERENCES artifacts(id) ON DELETE SET NULL, blob_id TEXT NOT NULL REFERENCES artifact_blob(id) ON DELETE RESTRICT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, link_type TEXT NOT NULL DEFAULT 'references', role TEXT, repo_id TEXT, provider_id TEXT, source TEXT NOT NULL DEFAULT 'artifact_registry', metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, link_kind TEXT NOT NULL DEFAULT 'pinned' CHECK(link_kind IN ('pinned','living')), series_id TEXT, series_ref TEXT, target_type TEXT NOT NULL CHECK(target_type IN ('artifact','artifact_version','artifact_blob')), target_id TEXT NOT NULL, fallback_version_id TEXT REFERENCES artifact_version(id) ON DELETE RESTRICT, legacy_blob_id TEXT, CHECK ( (link_kind = 'living' AND target_type = 'artifact') OR (link_kind = 'pinned' AND target_type IN ('artifact_version','artifact_blob')) ) );
CREATE TABLE artifact_series ( id TEXT PRIMARY KEY, series_key TEXT NOT NULL, source_kind TEXT NOT NULL DEFAULT 'managed' CHECK(source_kind IN ('tracked_repo','local_only','managed','mixed')), title TEXT, repo_id TEXT, logical_name TEXT, latest_version_id TEXT, version_count INTEGER NOT NULL DEFAULT 0, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(series_key) );
CREATE TABLE artifact_version ( id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES artifact(id) ON DELETE CASCADE, version_no INTEGER NOT NULL, blob_id TEXT NOT NULL REFERENCES artifact_blob(id) ON DELETE RESTRICT, source_kind TEXT NOT NULL CHECK(source_kind IN ('tracked_repo','local_only','managed','external')), content_hash TEXT NOT NULL, source_project_id TEXT REFERENCES ledger_projects(id) ON DELETE RESTRICT, source_repo_id TEXT, repo_path TEXT, commit_sha TEXT, observed_path TEXT, source_locator_json TEXT NOT NULL DEFAULT '{}', custody_mode TEXT CHECK(custody_mode IS NULL OR custody_mode IN ('link','copy','managed','external')), label TEXT, note TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, UNIQUE(artifact_id, version_no) );
CREATE TABLE artifact_versions ( id TEXT PRIMARY KEY, series_id TEXT NOT NULL REFERENCES artifact_series(id) ON DELETE CASCADE, artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE RESTRICT, version_no INTEGER NOT NULL, source_kind TEXT NOT NULL CHECK(source_kind IN ('tracked_repo','local_only','managed')), content_hash TEXT NOT NULL, commit_sha TEXT, repo_path TEXT, observed_path TEXT, custody_mode TEXT, label TEXT, note TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, parent_version_id TEXT, UNIQUE(series_id, version_no) );
CREATE TABLE artifacts ( id TEXT PRIMARY KEY, algorithm TEXT NOT NULL DEFAULT 'sha256', content_hash TEXT NOT NULL, uri TEXT NOT NULL, media_type TEXT, role TEXT, size_bytes INTEGER NOT NULL DEFAULT 0, provider_id TEXT, manifest_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', pinned INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, custody_mode TEXT NOT NULL DEFAULT 'managed' CHECK(custody_mode IN ('link','copy','managed','external')), home_repo_id TEXT, repo_locator_json TEXT NOT NULL DEFAULT '{}', availability TEXT NOT NULL DEFAULT 'unchecked' CHECK(availability IN ('present','missing','stale','unchecked','remote_only','pinned')), retention_json TEXT NOT NULL DEFAULT '{}', reference_json TEXT NOT NULL DEFAULT '{}', UNIQUE(algorithm, content_hash) );
CREATE TABLE attribution_evidence ( id TEXT PRIMARY KEY, evidence_method TEXT NOT NULL, credential_id TEXT REFERENCES user_credentials(id) ON DELETE SET NULL, lease_id TEXT REFERENCES delegated_signing_leases(id) ON DELETE SET NULL, verified_at INTEGER NOT NULL, details_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(details_json) AND json_type(details_json)='object') );
CREATE TABLE auth_hooks ( id TEXT PRIMARY KEY, repo_pattern TEXT NOT NULL DEFAULT '*', auth_type TEXT NOT NULL DEFAULT 'merge', command TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, builtin INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL , required INTEGER NOT NULL DEFAULT 1);
CREATE TABLE auth_hook_alerts ( id TEXT PRIMARY KEY, auth_request_id TEXT NOT NULL, hook_id TEXT NOT NULL, hook_label TEXT NOT NULL DEFAULT '', session_id TEXT, repo TEXT, detail TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, acknowledged_at INTEGER, acknowledged_by TEXT, UNIQUE(auth_request_id, hook_id) );
CREATE TABLE auth_hook_executions ( id TEXT PRIMARY KEY, auth_request_id TEXT NOT NULL, hook_id TEXT NOT NULL, hook_label TEXT NOT NULL DEFAULT '', command TEXT NOT NULL, command_digest TEXT NOT NULL CHECK(length(command_digest) = 64), position INTEGER NOT NULL DEFAULT 0, required INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','running','complete','failed')), attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts >= 0), max_attempts INTEGER NOT NULL DEFAULT 3 CHECK(max_attempts >= 1), exit_code INTEGER, output TEXT NOT NULL DEFAULT '', attempt_history TEXT NOT NULL DEFAULT '[]', started_at INTEGER, finished_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(auth_request_id, hook_id) );
CREATE TABLE "auth_request_actions" ( id TEXT PRIMARY KEY, auth_request_id TEXT NOT NULL REFERENCES auth_requests(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('comment_add','issue_close','worker_status_set','label_add','label_rm','checkpoint_add','link_add','briefing_group_promote')), target_issue_ref TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'staged' CHECK(state IN ('staged','applied','failed','vetoed','skipped_stale')), target_digest TEXT, staged_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, applied_at INTEGER, outcome_detail TEXT );
CREATE TABLE auth_requests ( id TEXT PRIMARY KEY, session_id TEXT, command TEXT NOT NULL, title TEXT NOT NULL, cwd TEXT, diff_summary TEXT, spec_content TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, approved_at INTEGER, resolved_at INTEGER, skipped_at INTEGER, expires_at INTEGER NOT NULL, exit_code INTEGER, output TEXT NOT NULL DEFAULT '', error TEXT , repo TEXT, base_branch TEXT, head_branch TEXT, files_changed INTEGER DEFAULT 0, additions INTEGER DEFAULT 0, deletions INTEGER DEFAULT 0, execution_mode TEXT NOT NULL DEFAULT 'daemon', commit_message TEXT, last_executed_at INTEGER, acknowledged_by TEXT, post_merge_handoff TEXT, issue_ids TEXT, depends_on_id TEXT, issues TEXT, type TEXT NOT NULL DEFAULT 'merge', target_session_id TEXT, target_repo_root TEXT, delivered_at INTEGER, conversation_id TEXT, approval_source TEXT NOT NULL DEFAULT 'manual', approval_lease_id TEXT, issue_references TEXT, issue_closures TEXT, merge_preflight_base_sha TEXT, merge_preflight_queue_fingerprint TEXT, merge_head_sha TEXT, merge_finalized_at INTEGER, requested_by_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, approved_by_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, execution_evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL, merge_finalizer_state TEXT, merge_candidate_tree_sha TEXT, merge_candidate_pin_sha TEXT, merge_atomic_enabled INTEGER NOT NULL DEFAULT 0, commit_message_digest TEXT, requester_evidence_method TEXT, requester_credential_id TEXT REFERENCES user_credentials(id) ON DELETE RESTRICT, clearance_use_id TEXT REFERENCES auth_clearance_uses(id) ON DELETE RESTRICT);
CREATE TABLE auth_request_merge_succeeded_facts ( auth_request_id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, base_branch TEXT NOT NULL, completed_at INTEGER NOT NULL, canonical_message INTEGER NOT NULL CHECK(canonical_message IN (0,1)), recorded_at INTEGER NOT NULL );
CREATE TABLE branches ( repo_root TEXT NOT NULL, branch TEXT NOT NULL, is_current INTEGER NOT NULL DEFAULT 0, is_worktree INTEGER DEFAULT 0, worktree_path TEXT, is_dirty INTEGER DEFAULT 0, ahead INTEGER DEFAULT 0, behind INTEGER DEFAULT 0, last_commit_hash TEXT, last_commit_message TEXT, last_commit_author TEXT, last_commit_date TEXT, diff_stat TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now')), ahead_default INTEGER DEFAULT 0, behind_default INTEGER DEFAULT 0, default_branch TEXT DEFAULT '', worktree_inventory_known INTEGER NOT NULL DEFAULT 0, worktree_status_known INTEGER NOT NULL DEFAULT 0, default_comparison_known INTEGER NOT NULL DEFAULT 0, has_upstream INTEGER NOT NULL DEFAULT 0, upstream TEXT, PRIMARY KEY (repo_root, branch) );
CREATE TABLE console_session_telemetry ( telemetry_key TEXT PRIMARY KEY, console_session_id TEXT REFERENCES console_sessions(id) ON DELETE CASCADE, provider_session_id TEXT, transcript_path TEXT, model TEXT, context_used_percentage REAL, context_window_size INTEGER, context_input_tokens INTEGER, context_output_tokens INTEGER, context_cache_creation_input_tokens INTEGER, context_cache_read_input_tokens INTEGER, rate_limit_five_hour_used_percentage REAL, rate_limit_five_hour_resets_at TEXT, rate_limit_seven_day_used_percentage REAL, rate_limit_seven_day_resets_at TEXT, raw_payload_json TEXT NOT NULL, received_at INTEGER NOT NULL );
CREATE TABLE console_session_usage ( id TEXT PRIMARY KEY, console_session_id TEXT NOT NULL, provider_session_id TEXT, recorded_at INTEGER NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, cache_creation_input_tokens INTEGER NOT NULL DEFAULT 0, cache_read_input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, web_search_requests INTEGER NOT NULL DEFAULT 0, cost_usd REAL NOT NULL DEFAULT 0, total_cost_usd REAL NOT NULL DEFAULT 0, duration_ms INTEGER NOT NULL DEFAULT 0, num_turns INTEGER NOT NULL DEFAULT 0, is_error INTEGER NOT NULL DEFAULT 0, result_subtype TEXT, usage_json TEXT NOT NULL DEFAULT '{}', model_usage_json TEXT NOT NULL DEFAULT '{}', errors_json TEXT NOT NULL DEFAULT '[]', FOREIGN KEY (console_session_id) REFERENCES console_sessions(id) ON DELETE CASCADE );
CREATE TABLE console_sessions ( id TEXT PRIMARY KEY, label TEXT NOT NULL, command TEXT NOT NULL, args_json TEXT NOT NULL DEFAULT '[]', cwd TEXT, env_json TEXT NOT NULL DEFAULT '{}', cols INTEGER NOT NULL DEFAULT 120, rows INTEGER NOT NULL DEFAULT 30, status TEXT NOT NULL DEFAULT 'stopped', pid INTEGER, exit_code INTEGER, auto_restart INTEGER NOT NULL DEFAULT 0, is_operator INTEGER NOT NULL DEFAULT 0, interaction_mode TEXT NOT NULL DEFAULT 'both', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, started_at INTEGER, stopped_at INTEGER , provider_session_id TEXT, backend_type TEXT NOT NULL DEFAULT 'pty', allowed_tools TEXT, mandible_session_id TEXT, resume_at_message TEXT, channel_enabled INTEGER NOT NULL DEFAULT 0, transport_lane TEXT NOT NULL DEFAULT 'pty', owner_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, run_options_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(run_options_json) AND json_type(run_options_json) = 'object'));
CREATE TABLE convention_setting_links ( id TEXT PRIMARY KEY, node_id TEXT NOT NULL REFERENCES preset_nodes(id) ON DELETE CASCADE, setting_key TEXT NOT NULL, link_type TEXT NOT NULL DEFAULT 'references' CHECK(link_type IN ('references', 'requires', 'configures')), created_at INTEGER NOT NULL, source TEXT NOT NULL DEFAULT 'manual', UNIQUE(node_id, setting_key) );
CREATE TABLE conversation_blocks ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, type TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL, timestamp TEXT, parent_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', dag_uuid TEXT, dag_parent_uuid TEXT, compressed INTEGER NOT NULL DEFAULT 0, timestamp_ms INTEGER, payload_state TEXT NOT NULL DEFAULT 'legacy' CHECK(payload_state IN ('legacy','source')), UNIQUE(conversation_id, position) );
CREATE TABLE conversation_ingest_state ( file_path TEXT PRIMARY KEY, byte_offset INTEGER NOT NULL DEFAULT 0, line_count INTEGER NOT NULL DEFAULT 0, tail_hash TEXT NOT NULL DEFAULT '', partial_line TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL , empty_source_mtime REAL, empty_source_size INTEGER);
CREATE TABLE conversations ( id TEXT PRIMARY KEY, source TEXT NOT NULL CHECK(source IN ('claude_code', 'codex', 'gemini')), source_path TEXT NOT NULL, source_hash TEXT NOT NULL, source_mtime INTEGER NOT NULL, title TEXT NOT NULL DEFAULT '', summary TEXT, started_at TEXT NOT NULL, ended_at TEXT, block_count INTEGER NOT NULL DEFAULT 0, session_id TEXT NOT NULL, project_path TEXT, cwd TEXT, branch TEXT, model TEXT, cli_version TEXT, starred INTEGER NOT NULL DEFAULT 0, notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')) , parent_conversation_id TEXT REFERENCES conversations(id) ON DELETE SET NULL, is_sidechain INTEGER NOT NULL DEFAULT 0, agent_id TEXT, started_at_ms INTEGER, ended_at_ms INTEGER, created_at_ms INTEGER, updated_at_ms INTEGER, tags TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(tags) AND json_type(tags) = 'array'));
CREATE TABLE daemon_log ( id TEXT PRIMARY KEY, ts INTEGER NOT NULL, level TEXT NOT NULL CHECK(level IN ('debug','info','warn','error')), event TEXT NOT NULL, subsystem TEXT NOT NULL DEFAULT 'daemon', fields_json TEXT NOT NULL DEFAULT '{}', issue_id TEXT, auth_request_id TEXT, artifact_id TEXT, session_id TEXT, repo_id TEXT );
CREATE TABLE delegated_signing_leases ( id TEXT PRIMARY KEY, credential_id TEXT NOT NULL REFERENCES user_credentials(id) ON DELETE RESTRICT, owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, minted_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, mint_method TEXT NOT NULL CHECK(mint_method IN ('fresh_presence','reused_lease')) );
CREATE TABLE graph_edges ( id TEXT PRIMARY KEY, source_id TEXT NOT NULL, target_id TEXT NOT NULL, edge_type TEXT NOT NULL, edge_class TEXT NOT NULL DEFAULT 'provenance', provenance TEXT NOT NULL DEFAULT 'system', confidence TEXT NOT NULL DEFAULT 'observed', metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER, observed_at INTEGER NOT NULL, source TEXT NOT NULL );
CREATE TABLE graph_entities ( id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, repo_id TEXT, provider_id TEXT, external_id TEXT, title TEXT NOT NULL, status TEXT, labels_json TEXT NOT NULL DEFAULT '[]', summary_json TEXT NOT NULL DEFAULT '{}', detail_ref_json TEXT NOT NULL DEFAULT '{}', action_context_json TEXT NOT NULL DEFAULT '{}', visual_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER, updated_at INTEGER, observed_at INTEGER NOT NULL, source TEXT NOT NULL );
CREATE TABLE issue_branches ( issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, branch TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'primary' CHECK(role IN ('primary','superseded')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (issue_id, branch) );
CREATE TABLE issue_resolutions ( issue_id TEXT NOT NULL, commit_sha TEXT NOT NULL, repo_id TEXT NOT NULL, resolved_at INTEGER NOT NULL, PRIMARY KEY (issue_id, commit_sha) );
CREATE TABLE knowledge_backrefs ( id TEXT PRIMARY KEY, source_type TEXT NOT NULL CHECK(source_type IN ('artifact','document')), source_id TEXT NOT NULL, provider_id TEXT NOT NULL DEFAULT 'humbleb', ref_type TEXT NOT NULL CHECK(ref_type IN ('document','entity','claim')), external_id TEXT NOT NULL, external_ref TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'returned' CHECK(status IN ('offered','indexed','returned')), metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(source_type, source_id, provider_id, ref_type, external_id) );
CREATE TABLE ledger_auth_issue_links ( auth_request_id TEXT NOT NULL REFERENCES auth_requests(id) ON DELETE CASCADE, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE RESTRICT, link_type TEXT NOT NULL DEFAULT 'references', source TEXT NOT NULL DEFAULT 'auth_queue', created_at INTEGER NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (auth_request_id, issue_id, link_type) );
CREATE TABLE ledger_body_revisions ( id TEXT PRIMARY KEY, entity_type TEXT NOT NULL CHECK(entity_type IN ('issue_body','comment_body')), entity_id TEXT NOT NULL, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, revision_no INTEGER NOT NULL, event_id TEXT UNIQUE REFERENCES ledger_events(id) ON DELETE SET NULL, actor_id TEXT, actor_type TEXT NOT NULL CHECK(actor_type IN ('mandible_user','agent','system','external_adapter')), source TEXT NOT NULL CHECK(source IN ('mandible','git_bug','auth_queue','session','work_unit','import','system')), reason TEXT NOT NULL DEFAULT 'edit' CHECK(reason IN ('create','edit','import_snapshot','external_update','normalize','migration_snapshot','restore')), occurred_at INTEGER NOT NULL, observed_at INTEGER NOT NULL, base_revision_id TEXT REFERENCES ledger_body_revisions(id) ON DELETE SET NULL, base_hash TEXT, new_hash TEXT NOT NULL, snapshot_body TEXT NOT NULL, patch_format TEXT, patch_text TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', redacted_at INTEGER, redacted_by_actor_id TEXT, redaction_reason TEXT, actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT, evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL, redacted_by_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, UNIQUE(entity_type, entity_id, revision_no) );
CREATE TABLE ledger_comments ( id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL DEFAULT 0, body TEXT NOT NULL, author_actor_id TEXT, author_actor_type TEXT NOT NULL CHECK(author_actor_type IN ('mandible_user','agent','system','external_adapter')), author_display TEXT NOT NULL DEFAULT '', source TEXT NOT NULL CHECK(source IN ('mandible','git_bug','auth_queue','session','work_unit','import','system')), created_at INTEGER NOT NULL, updated_at INTEGER, deleted_at INTEGER , author_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT, evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL);
CREATE TABLE ledger_commit_issue_links ( commit_sha TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE RESTRICT, link_type TEXT NOT NULL DEFAULT 'fixed_by', source TEXT NOT NULL DEFAULT 'auth_queue', created_at INTEGER NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (commit_sha, issue_id, link_type) );
CREATE TABLE ledger_conflicts ( id TEXT PRIMARY KEY, adapter TEXT NOT NULL, project_id TEXT NOT NULL DEFAULT '', entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, field TEXT NOT NULL, local_value_json TEXT NOT NULL, remote_value_json TEXT NOT NULL, base_value_json TEXT NOT NULL DEFAULT 'null', status TEXT NOT NULL CHECK(status IN ('open','resolved','dismissed')), resolution TEXT, created_at INTEGER NOT NULL, resolved_at INTEGER );
CREATE TABLE ledger_events ( id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, event_type TEXT NOT NULL, actor_id TEXT, actor_type TEXT NOT NULL CHECK(actor_type IN ('mandible_user','agent','system','external_adapter')), source TEXT NOT NULL CHECK(source IN ('mandible','git_bug','auth_queue','session','work_unit','import','system')), payload_json TEXT NOT NULL DEFAULT '{}', occurred_at INTEGER NOT NULL, observed_at INTEGER NOT NULL , actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT, evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL);
CREATE TABLE ledger_external_refs ( id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, adapter TEXT NOT NULL, project_id TEXT NOT NULL DEFAULT '', external_id TEXT NOT NULL, external_kind TEXT NOT NULL, remote_version TEXT NOT NULL DEFAULT '', remote_hash TEXT NOT NULL DEFAULT '', last_imported_at INTEGER, last_exported_at INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(adapter, project_id, external_kind, external_id) );
CREATE TABLE ledger_issue_aliases ( issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, alias_kind TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE CASCADE, alias TEXT NOT NULL, external_id TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, PRIMARY KEY (alias_kind, project_id, alias) );
CREATE TABLE ledger_issue_checkpoints ( id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, kind TEXT NOT NULL, payload_json TEXT NOT NULL, author_actor_id TEXT, author_actor_type TEXT NOT NULL CHECK(author_actor_type IN ('mandible_user','agent','system','external_adapter')), author_display TEXT NOT NULL DEFAULT '', source TEXT NOT NULL CHECK(source IN ('mandible','git_bug','auth_queue','session','work_unit','import','system')), created_at INTEGER NOT NULL , author_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT, evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL);
CREATE TABLE ledger_issue_relationship_sources ( id TEXT PRIMARY KEY, relationship_id TEXT NOT NULL REFERENCES ledger_issue_relationships(id) ON DELETE CASCADE, source_entity_type TEXT NOT NULL CHECK(source_entity_type IN ('issue_body','comment')), source_entity_id TEXT NOT NULL, source_issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, target_issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, relationship_type TEXT NOT NULL CHECK(relationship_type IN ('parent_child','blocks','duplicate_of','related','references','fixed_by','caused_by','implements','tests')), ref_kind TEXT NOT NULL CHECK(ref_kind IN ('issue','comment')), raw_ref TEXT NOT NULL, normalized_ref TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, UNIQUE(source_entity_type, source_entity_id, target_issue_id, relationship_type, ref_kind, normalized_ref) );
CREATE TABLE ledger_issue_relationships ( id TEXT PRIMARY KEY, source_issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, target_issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, relationship_type TEXT NOT NULL CHECK(relationship_type IN ('parent_child','blocks','duplicate_of','related','references','fixed_by','caused_by','implements','tests')), provenance TEXT NOT NULL DEFAULT 'manual' CHECK(provenance IN ('manual','imported','derived','system')), confidence TEXT NOT NULL DEFAULT 'observed', metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, UNIQUE(source_issue_id, target_issue_id, relationship_type) );
CREATE TABLE ledger_issues ( id TEXT PRIMARY KEY, short_id TEXT NOT NULL DEFAULT '', project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('open','closed')), resolution TEXT CHECK(resolution IN ('fixed','merged','duplicate','wontfix','invalid','obsolete','unknown') OR resolution IS NULL), kind TEXT NOT NULL DEFAULT 'unknown' CHECK(kind IN ('bug','feature','umbrella','task','question','maintenance','deferred','unknown')), priority TEXT NOT NULL DEFAULT 'unknown' CHECK(priority IN ('low','normal','high','urgent','unknown')), author_actor_id TEXT, author_actor_type TEXT NOT NULL DEFAULT 'external_adapter' CHECK(author_actor_type IN ('mandible_user','agent','system','external_adapter')), author_display TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'mandible' CHECK(source IN ('mandible','git_bug','auth_queue','session','work_unit','import','system')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, closed_at INTEGER, deleted_at INTEGER , worker_status TEXT NOT NULL DEFAULT 'none' CHECK(worker_status IN ('none','in_progress','done','blocked','pivot-needed')), author_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT, evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL);
CREATE TABLE ledger_labels ( issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, label TEXT NOT NULL, source TEXT NOT NULL DEFAULT 'mandible', created_at INTEGER NOT NULL, deleted_at INTEGER, PRIMARY KEY (issue_id, label) );
CREATE TABLE ledger_operational_link_mismatches ( id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES ledger_operational_link_reports(id) ON DELETE CASCADE, source_table TEXT NOT NULL, source_id TEXT NOT NULL, repo_id TEXT NOT NULL DEFAULT '', issue_ref TEXT NOT NULL DEFAULT '', mismatch_type TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL );
CREATE TABLE ledger_operational_link_reports ( id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('clean','incomplete','failed')), resolved_count INTEGER NOT NULL DEFAULT 0, unresolved_count INTEGER NOT NULL DEFAULT 0, ambiguous_count INTEGER NOT NULL DEFAULT 0, source_counts_json TEXT NOT NULL DEFAULT '{}', error TEXT, started_at INTEGER NOT NULL, finished_at INTEGER );
CREATE TABLE ledger_outbox ( id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES ledger_events(id) ON DELETE CASCADE, adapter TEXT NOT NULL, project_id TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('pending','processing','applied','failed','conflicted','skipped')), attempt_count INTEGER NOT NULL DEFAULT 0, available_at INTEGER NOT NULL, last_attempt_at INTEGER, error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(event_id, adapter) );
CREATE TABLE ledger_project_checkouts ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, work_repo_id TEXT, root TEXT NOT NULL, name TEXT NOT NULL, default_branch TEXT NOT NULL DEFAULT '', remote_url TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(root) );
CREATE TABLE ledger_projects ( id TEXT PRIMARY KEY, display_name TEXT NOT NULL, remote_identity TEXT NOT NULL DEFAULT '', upstream_identity TEXT NOT NULL DEFAULT '', namespace_policy TEXT NOT NULL DEFAULT 'remote' CHECK(namespace_policy IN ('remote','upstream','local')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL , project_key TEXT NOT NULL DEFAULT '', restricted INTEGER NOT NULL DEFAULT 0 CHECK(restricted IN (0, 1)));
CREATE TABLE ledger_reconciliation_mismatches ( id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES ledger_reconciliation_reports(id) ON DELETE CASCADE, project_id TEXT NOT NULL DEFAULT '', repo_id TEXT NOT NULL DEFAULT '', issue_ref TEXT NOT NULL DEFAULT '', mismatch_type TEXT NOT NULL, scanner_value_json TEXT NOT NULL DEFAULT 'null', ledger_value_json TEXT NOT NULL DEFAULT 'null', metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL );
CREATE TABLE ledger_reconciliation_reports ( id TEXT PRIMARY KEY, read_mode TEXT NOT NULL CHECK(read_mode IN ('scanner','shadow','ledger')), status TEXT NOT NULL CHECK(status IN ('running','clean','mismatch','failed')), scanner_issue_count INTEGER NOT NULL DEFAULT 0, ledger_issue_count INTEGER NOT NULL DEFAULT 0, scanner_open_count INTEGER NOT NULL DEFAULT 0, ledger_open_count INTEGER NOT NULL DEFAULT 0, scanner_closed_count INTEGER NOT NULL DEFAULT 0, ledger_closed_count INTEGER NOT NULL DEFAULT 0, mismatch_count INTEGER NOT NULL DEFAULT 0, summary_json TEXT NOT NULL DEFAULT '{}', error TEXT, started_at INTEGER NOT NULL, finished_at INTEGER );
CREATE TABLE ledger_relationship_edges ( id TEXT PRIMARY KEY, source_entity_type TEXT NOT NULL CHECK(source_entity_type IN ('issue','comment')), source_entity_id TEXT NOT NULL, source_project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, source_issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, target_entity_type TEXT NOT NULL CHECK(target_entity_type IN ('issue','comment')), target_entity_id TEXT NOT NULL, target_project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, target_issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE CASCADE, link_type TEXT NOT NULL CHECK(link_type IN ('parent_child','blocks','duplicate_of','related','references','fixed_by','caused_by','implements','tests')), provenance TEXT NOT NULL DEFAULT 'manual' CHECK(provenance IN ('manual','imported','derived','system')), note TEXT, action_id TEXT NOT NULL, actor_id TEXT, actor_type TEXT NOT NULL CHECK(actor_type IN ('mandible_user','agent','system','external_adapter')), source TEXT NOT NULL CHECK(source IN ('mandible','git_bug','auth_queue','session','work_unit','import','system')), metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT, evidence_id TEXT REFERENCES attribution_evidence(id) ON DELETE SET NULL, UNIQUE(source_entity_type, source_entity_id, target_entity_type, target_entity_id, link_type) );
CREATE TABLE ledger_session_issue_links ( session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE RESTRICT, link_type TEXT NOT NULL DEFAULT 'worked_on', source TEXT NOT NULL DEFAULT 'system', created_at INTEGER NOT NULL, last_seen_at INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (session_id, issue_id, link_type) );
CREATE TABLE ledger_sync_jobs ( id TEXT PRIMARY KEY, adapter TEXT NOT NULL, project_id TEXT NOT NULL DEFAULT '', checkout_id TEXT, root TEXT NOT NULL DEFAULT '', direction TEXT NOT NULL CHECK(direction IN ('import','export','full')), status TEXT NOT NULL CHECK(status IN ('pending','running','completed','failed','retryable','conflicted')), attempt_count INTEGER NOT NULL DEFAULT 0, next_retry_at INTEGER, started_at INTEGER, finished_at INTEGER, last_error TEXT, stats_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE ledger_work_unit_issue_links ( work_unit_id TEXT NOT NULL REFERENCES work_units(id) ON DELETE CASCADE, issue_id TEXT NOT NULL REFERENCES ledger_issues(id) ON DELETE RESTRICT, link_type TEXT NOT NULL DEFAULT 'work_unit_tracks', source TEXT NOT NULL DEFAULT 'system', created_at INTEGER NOT NULL, last_seen_at INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', PRIMARY KEY (work_unit_id, issue_id, link_type) );
CREATE TABLE message_params ( id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, message_index INTEGER NOT NULL, model TEXT, permission_mode TEXT, max_turns INTEGER, max_cost_usd REAL, preset_ids TEXT, allowed_tools TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), thinking_effort TEXT, UNIQUE(session_id, message_index) );
CREATE TABLE meta ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE TABLE managed_tasks ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK(kind = 'mandible-reminder'), lifecycle TEXT NOT NULL CHECK(lifecycle IN ('armed','completed','cancelled')), active_revision_id TEXT NOT NULL REFERENCES managed_task_revisions(id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, created_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, completed_at INTEGER, cancelled_at INTEGER, CHECK ( (lifecycle = 'armed' AND completed_at IS NULL AND cancelled_at IS NULL) OR (lifecycle = 'completed' AND completed_at IS NOT NULL AND cancelled_at IS NULL) OR (lifecycle = 'cancelled' AND completed_at IS NULL AND cancelled_at IS NOT NULL) ) );
CREATE TABLE managed_task_revisions ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES managed_tasks(id) ON DELETE RESTRICT, revision_no INTEGER NOT NULL CHECK(revision_no = 1), schema_id TEXT NOT NULL CHECK(schema_id = 'mandible-reminder@1'), payload_json TEXT NOT NULL CHECK( json_valid(payload_json) AND json_type(payload_json) = 'object' AND json_extract(payload_json, '$.schema') = 'mandible-reminder@1' AND json_extract(payload_json, '$.effect.kind') = 'inbox_occurrence' ), payload_digest TEXT NOT NULL CHECK( length(payload_digest) = 64 AND payload_digest NOT GLOB '*[^0-9a-f]*' ), created_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, UNIQUE(task_id), UNIQUE(task_id, id), UNIQUE(task_id, revision_no) );
CREATE TABLE managed_task_create_requests ( id TEXT PRIMARY KEY, created_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, idempotency_key TEXT NOT NULL CHECK(trim(idempotency_key) != ''), request_digest TEXT NOT NULL CHECK( length(request_digest) = 64 AND request_digest NOT GLOB '*[^0-9a-f]*' ), task_id TEXT NOT NULL REFERENCES managed_tasks(id) ON DELETE RESTRICT, result_json TEXT NOT NULL CHECK( json_valid(result_json) AND json_type(result_json) = 'object' ), created_at INTEGER NOT NULL, UNIQUE(created_by_user_id, idempotency_key), UNIQUE(task_id) );
CREATE TABLE managed_task_occurrences ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES managed_tasks(id) ON DELETE RESTRICT, revision_id TEXT NOT NULL, occurrence_key TEXT NOT NULL CHECK(trim(occurrence_key) != ''), kind TEXT NOT NULL CHECK(kind = 'inbox_occurrence'), payload_json TEXT NOT NULL CHECK( json_valid(payload_json) AND json_type(payload_json) = 'object' ), triggering_evidence_json TEXT NOT NULL CHECK( json_valid(triggering_evidence_json) AND json_type(triggering_evidence_json) = 'object' ), created_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, fired_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, acknowledged_by TEXT, acknowledged_at INTEGER, UNIQUE(task_id, revision_id, occurrence_key), FOREIGN KEY(task_id, revision_id) REFERENCES managed_task_revisions(task_id, id) ON DELETE RESTRICT );
CREATE TABLE managed_task_events ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES managed_tasks(id) ON DELETE RESTRICT, revision_id TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, event_type TEXT NOT NULL CHECK(event_type IN ('created','completed','cancelled')), actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, evidence_method TEXT NOT NULL CHECK(evidence_method IN ('api_token','ephemeral','system_internal')), payload_json TEXT NOT NULL DEFAULT '{}' CHECK( json_valid(payload_json) AND json_type(payload_json) = 'object' ), occurred_at INTEGER NOT NULL, FOREIGN KEY(task_id, revision_id) REFERENCES managed_task_revisions(task_id, id) ON DELETE RESTRICT );
CREATE INDEX idx_managed_tasks_reconcile ON managed_tasks(lifecycle, created_at, id);
CREATE INDEX idx_managed_tasks_project ON managed_tasks(project_id, created_at DESC, id DESC);
CREATE INDEX idx_managed_task_occurrences_created ON managed_task_occurrences(created_at DESC, id DESC);
CREATE INDEX idx_managed_task_occurrences_inbox ON managed_task_occurrences(acknowledged_at, created_at DESC, id DESC);
CREATE INDEX idx_managed_task_events_task ON managed_task_events(task_id, occurred_at, id);
CREATE TRIGGER trg_managed_task_revisions_immutable_update BEFORE UPDATE ON managed_task_revisions BEGIN SELECT RAISE(ABORT, 'managed task revisions are immutable'); END;
CREATE TRIGGER trg_managed_task_revisions_immutable_delete BEFORE DELETE ON managed_task_revisions BEGIN SELECT RAISE(ABORT, 'managed task revisions are immutable'); END;
CREATE TRIGGER trg_managed_task_revision_matches_task AFTER INSERT ON managed_task_revisions WHEN (SELECT active_revision_id FROM managed_tasks WHERE id = NEW.task_id) != NEW.id BEGIN SELECT RAISE(ABORT, 'managed task active revision mismatch'); END;
CREATE TRIGGER trg_managed_task_active_revision_immutable BEFORE UPDATE OF active_revision_id ON managed_tasks BEGIN SELECT RAISE(ABORT, 'managed task active revision is immutable'); END;
CREATE TABLE preset_diffs ( id TEXT PRIMARY KEY, session_id TEXT NOT NULL, preset_id TEXT, node_id TEXT, diff_type TEXT NOT NULL CHECK(diff_type IN ('add', 'remove', 'modify')), old_content TEXT, new_content TEXT, status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN ('proposed', 'accepted', 'rejected', 'promoted')), created_at INTEGER NOT NULL );
CREATE TABLE preset_nodes ( id TEXT PRIMARY KEY, preset_id TEXT NOT NULL REFERENCES presets(id) ON DELETE CASCADE, parent_id TEXT REFERENCES preset_nodes(id) ON DELETE CASCADE, position INTEGER NOT NULL DEFAULT 0, title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', level INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE presets ( id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('manual', 'claude_md_global', 'claude_md_project', 'claude_md_local')), source_path TEXT, content_hash TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE project_artifact_associations ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, target_type TEXT NOT NULL CHECK(target_type IN ('artifact','artifact_version')), target_id TEXT NOT NULL, association_kind TEXT NOT NULL DEFAULT 'associated' CHECK(association_kind IN ('associated','canonical')), role TEXT NOT NULL DEFAULT '', title TEXT, description TEXT, rank INTEGER, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','superseded','archived')), source TEXT NOT NULL DEFAULT 'user' CHECK(source IN ('user','agent_explicit','space_rule','migration','system')), source_ref_type TEXT, source_ref_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(project_id, target_type, target_id, role) );
CREATE TABLE permission_grants ( id TEXT PRIMARY KEY, subject_type TEXT NOT NULL CHECK(subject_type IN ('user','group')), subject_id TEXT NOT NULL, resource_type TEXT NOT NULL CHECK(resource_type IN ('project','global')), resource_id TEXT REFERENCES ledger_projects(id) ON DELETE CASCADE, permission TEXT NOT NULL, created_at INTEGER NOT NULL, CHECK ( (resource_type = 'project' AND resource_id IS NOT NULL AND permission IN ('read','write','admin')) OR (resource_type = 'global' AND resource_id IS NULL AND permission IN ( 'approve_auth','spawn_console','change_settings','backup','open_path','ask.create' )) ) );
CREATE TABLE provider_manifests ( id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, manifest_type TEXT NOT NULL DEFAULT 'provider_manifest', version TEXT, content_hash TEXT NOT NULL, artifact_id TEXT, source TEXT NOT NULL DEFAULT 'ingest', content_json TEXT NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE providers ( id TEXT PRIMARY KEY, display_name TEXT NOT NULL, version TEXT, status TEXT NOT NULL DEFAULT 'active', transport TEXT NOT NULL DEFAULT 'manifest', endpoint TEXT, capabilities_json TEXT NOT NULL DEFAULT '{}', actions_json TEXT NOT NULL DEFAULT '[]', source TEXT NOT NULL DEFAULT 'local', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, last_seen_at INTEGER );
CREATE TABLE push_history ( id TEXT PRIMARY KEY, repo_id TEXT NOT NULL, repo_root TEXT NOT NULL, scope TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('started','completed','failed')), result_json TEXT, started_at INTEGER NOT NULL, completed_at INTEGER );
CREATE TABLE runtime_patches ( id TEXT PRIMARY KEY, fingerprint TEXT, commit_hash TEXT NOT NULL, parent_hash TEXT, diff_summary TEXT, diff_stat TEXT, applied_at INTEGER NOT NULL, reverted_at INTEGER, source TEXT NOT NULL CHECK(source IN ('agent','known_fix','manual','upstream_update')), session_id TEXT, submitted INTEGER NOT NULL DEFAULT 0, submission_url TEXT );
CREATE TABLE "session_instruction_artifacts" ( session_id TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES artifact(id) ON DELETE CASCADE, version_id TEXT NOT NULL REFERENCES artifact_version(id) ON DELETE RESTRICT, artifact_series_id TEXT REFERENCES artifact_series(id) ON DELETE SET NULL, artifact_version_id TEXT REFERENCES artifact_versions(id) ON DELETE SET NULL, legacy_preset_id TEXT, position INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (session_id, artifact_id) );
CREATE TABLE session_issues ( session_id TEXT NOT NULL, issue_id TEXT NOT NULL, repo_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (session_id, issue_id, repo_id) );
CREATE TABLE session_presets ( session_id TEXT NOT NULL, preset_id TEXT NOT NULL, preset_version INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (session_id, preset_id) );
CREATE TABLE session_projects ( session_id TEXT NOT NULL, repo_id TEXT NOT NULL, repo_name TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (session_id, repo_id) );
CREATE TABLE sessions ( id TEXT PRIMARY KEY, app TEXT NOT NULL, parent_id TEXT REFERENCES sessions(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'active', pid INTEGER, pid_start TEXT, cwd TEXT, branch TEXT, worktree TEXT, task TEXT, terminal TEXT, multiplexer TEXT, nav_session TEXT, nav_tab TEXT, nav_pane_id TEXT, nav_extra TEXT, agent_type TEXT, description TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), ended_at TEXT, updated_at TEXT NOT NULL DEFAULT (datetime('now')) , nav_metadata_status TEXT NOT NULL DEFAULT 'not_applicable', nav_metadata_attempts INTEGER NOT NULL DEFAULT 0, nav_metadata_last_error TEXT, nav_metadata_last_attempt_at TEXT, nav_metadata_next_retry_at TEXT, continuation TEXT, continuation_acked_by TEXT, pinned INTEGER DEFAULT 0, last_active TEXT, channel_connected_at INTEGER, channel_last_tool_call INTEGER, conversation_id TEXT, owner_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, identity_mismatch_at INTEGER, identity_mismatch_json TEXT);
CREATE TABLE settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE space_blocks ( id TEXT NOT NULL, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, parent_id TEXT, block_type TEXT NOT NULL CHECK(block_type IN ( 'heading','paragraph','reference','artifact_embed', 'issue_embed','comment_embed','todo' )), item_id TEXT, item_snapshot_json TEXT CHECK(item_snapshot_json IS NULL OR (json_valid(item_snapshot_json) AND json_type(item_snapshot_json)='object')), sort_key TEXT NOT NULL, markdown TEXT NOT NULL DEFAULT '', metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object'), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (id), UNIQUE (space_id, id), CHECK (item_id IS NULL OR item_snapshot_json IS NOT NULL), FOREIGN KEY (space_id, parent_id) REFERENCES space_blocks(space_id, id) ON DELETE CASCADE, FOREIGN KEY (space_id, item_id) REFERENCES space_items(space_id, id) ON DELETE RESTRICT );
CREATE TABLE space_edges ( id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, source TEXT NOT NULL, target TEXT NOT NULL, label TEXT, style TEXT, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object'), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY (space_id, source) REFERENCES space_occurrences(space_id, id) ON DELETE CASCADE, FOREIGN KEY (space_id, target) REFERENCES space_occurrences(space_id, id) ON DELETE CASCADE );
CREATE TABLE space_exports ( id TEXT PRIMARY KEY, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, repo_id TEXT NOT NULL REFERENCES ledger_project_checkouts(id) ON DELETE RESTRICT, branch TEXT NOT NULL, path TEXT NOT NULL, authority TEXT NOT NULL DEFAULT 'mandible' CHECK(authority IN ('mandible','repo')), status TEXT NOT NULL DEFAULT 'clean' CHECK(status IN ('clean','stale','repo_changed','worktree_dirty','conflict')), last_export_artifact_id TEXT REFERENCES artifacts(id) ON DELETE SET NULL, pre_export_snapshot_artifact_id TEXT REFERENCES artifacts(id) ON DELETE SET NULL, last_export_commit TEXT, last_export_blob_sha TEXT, last_export_content_sha256 TEXT, last_seen_commit TEXT, last_seen_content_sha256 TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, last_export_blob_id TEXT REFERENCES artifact_blob(id) ON DELETE SET NULL, pre_export_snapshot_blob_id TEXT REFERENCES artifact_blob(id) ON DELETE SET NULL, UNIQUE (repo_id, branch, path) );
CREATE TABLE space_occurrences ( id TEXT NOT NULL, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, item_id TEXT, renderer TEXT NOT NULL DEFAULT 'canvas' CHECK(renderer IN ('canvas','board','collection')), parent_id TEXT, x REAL, y REAL, width REAL, height REAL, z_index INTEGER, sort_key TEXT, section_id TEXT, note TEXT, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object'), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (id), UNIQUE (space_id, id), FOREIGN KEY (space_id, item_id) REFERENCES space_items(space_id, id) ON DELETE CASCADE, FOREIGN KEY (space_id, parent_id) REFERENCES space_occurrences(space_id, id) ON DELETE CASCADE );
CREATE TABLE spaces ( id TEXT PRIMARY KEY, project_id TEXT REFERENCES ledger_projects(id) ON DELETE RESTRICT, title TEXT NOT NULL, default_renderer TEXT NOT NULL DEFAULT 'canvas' CHECK(default_renderer IN ('canvas','document','board','collection')), description TEXT, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object'), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE starred_chats ( id TEXT PRIMARY KEY, session_id TEXT, label TEXT NOT NULL, notes TEXT, transcript_path TEXT, cwd TEXT, branch TEXT, created_at INTEGER NOT NULL DEFAULT (strftime('%s','now') * 1000) );
CREATE TABLE trash_entries ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, checkout_id TEXT NOT NULL REFERENCES ledger_project_checkouts(id) ON DELETE RESTRICT, repo_root TEXT NOT NULL, branch TEXT NOT NULL, issue_refs_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(issue_refs_json) AND json_type(issue_refs_json)='array'), reason TEXT NOT NULL CHECK(reason IN ('superseded','merged','abandoned','manual')), actor TEXT NOT NULL, snapshot_ref TEXT NOT NULL UNIQUE, snapshot_oid TEXT NOT NULL, original_oid TEXT NOT NULL, retention_policy TEXT NOT NULL DEFAULT 'trash-retention.v1', retention_days INTEGER NOT NULL CHECK(retention_days BETWEEN 1 AND 3650), state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ( 'active','remove_failed','restored','expired', 'restore_failed','gc_pending','gc_failed' )), created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, restored_at INTEGER, expired_at INTEGER, last_error TEXT, outcome_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(outcome_json) AND json_type(outcome_json)='object') );
CREATE TABLE user_bindings ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, binding_type TEXT NOT NULL CHECK(binding_type IN ('app_name','provider_session_env','process_pattern','git_author_email','external_author')), value TEXT NOT NULL, scope TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE user_credentials ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, type TEXT NOT NULL, fingerprint TEXT NOT NULL, public_material TEXT, label TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')), created_at INTEGER NOT NULL, revoked_at INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object') );
CREATE TABLE user_group_members ( group_id TEXT NOT NULL REFERENCES user_groups(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY (group_id, user_id) );
CREATE TABLE user_groups ( id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'custom' CHECK(kind IN ('system','custom')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE user_settings ( user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, key TEXT NOT NULL CHECK(key IN ('app_rail_order', 'ui_font_face', 'ui_font_size', 'detail_font_face', 'detail_font_size')), value TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision >= 1), updated_at INTEGER NOT NULL, PRIMARY KEY(user_id, key) );
CREATE TABLE users ( id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('human','agent','system','external')), display_name TEXT NOT NULL, email TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','retired')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object') );
CREATE TABLE webhook_events ( id TEXT PRIMARY KEY, source TEXT NOT NULL, event_type TEXT NOT NULL, title TEXT, data_json TEXT NOT NULL, target_session TEXT, target_issue TEXT, target_branch TEXT, priority TEXT NOT NULL DEFAULT 'normal', status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, delivered_at INTEGER, delivered_to TEXT );
CREATE TABLE work_repos ( id TEXT NOT NULL, root TEXT NOT NULL, name TEXT NOT NULL, default_branch TEXT NOT NULL DEFAULT '', dir_exists INTEGER NOT NULL DEFAULT 1, excluded INTEGER NOT NULL DEFAULT 0, user_modified INTEGER NOT NULL DEFAULT 0, last_scanned_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY (root) );
CREATE TABLE work_units ( id TEXT PRIMARY KEY, issue_id TEXT NOT NULL, repo_id TEXT NOT NULL, branch TEXT, parent_branch TEXT, kind TEXT NOT NULL DEFAULT 'solo', state TEXT NOT NULL DEFAULT 'open', assigned_session_id TEXT, provider TEXT, provider_session_id TEXT, continuation TEXT, continuation_by TEXT, continuation_at INTEGER, created_at INTEGER NOT NULL, activated_at INTEGER, last_commit_at INTEGER, resolved_at INTEGER, auth_request_id TEXT , ledger_issue_id TEXT REFERENCES ledger_issues(id), owner_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, merge_scan_retired_at INTEGER, worker_provider_session_id TEXT);
CREATE TABLE workflow_ingest_state ( file_path TEXT PRIMARY KEY, source_mtime REAL NOT NULL DEFAULT 0, summary_path TEXT NOT NULL, workflow_id TEXT, updated_at INTEGER NOT NULL );
CREATE TABLE workflow_phases ( id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE, phase_index INTEGER NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','completed','failed','warning')), worker_count INTEGER NOT NULL DEFAULT 0, completed_count INTEGER NOT NULL DEFAULT 0, UNIQUE(workflow_id, phase_index) );
CREATE TABLE workflow_runs ( id TEXT PRIMARY KEY, provider TEXT NOT NULL DEFAULT 'claude_code' CHECK(provider IN ('claude_code')), provider_run_id TEXT NOT NULL, session_id TEXT NOT NULL, project_path TEXT, summary_path TEXT NOT NULL UNIQUE, summary_mtime REAL NOT NULL DEFAULT 0, summary_hash TEXT NOT NULL DEFAULT '', workflow_name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','completed','failed','warning')), started_at INTEGER, updated_at INTEGER, completed_at INTEGER, duration_ms INTEGER, total_tokens INTEGER, total_tool_calls INTEGER, agent_count INTEGER NOT NULL DEFAULT 0, completed_workers INTEGER NOT NULL DEFAULT 0, total_workers INTEGER NOT NULL DEFAULT 0, format_version TEXT NOT NULL, script_path TEXT, warnings_json TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, ingested_at INTEGER NOT NULL );
CREATE TABLE workflow_workers ( id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE, phase_id TEXT REFERENCES workflow_phases(id) ON DELETE SET NULL, worker_index INTEGER NOT NULL, agent_id TEXT, label TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','completed','failed','warning')), model TEXT, queued_at INTEGER, started_at INTEGER, last_progress_at INTEGER, completed_at INTEGER, duration_ms INTEGER, tokens INTEGER, tool_calls INTEGER, last_tool_name TEXT, last_tool_summary TEXT, prompt_preview TEXT, result_preview TEXT, transcript_path TEXT, conversation_id TEXT REFERENCES conversations(id) ON DELETE SET NULL, warnings_json TEXT NOT NULL DEFAULT '[]', UNIQUE(workflow_id, agent_id) );
CREATE INDEX idx_artifact_aliases_artifact ON artifact_aliases(artifact_id) WHERE artifact_id IS NOT NULL;
CREATE INDEX idx_auth_merge_succeeded_project ON auth_request_merge_succeeded_facts( project_id, base_branch, canonical_message, completed_at, auth_request_id );
CREATE INDEX idx_artifact_aliases_blob ON artifact_aliases(blob_id) WHERE blob_id IS NOT NULL;
CREATE UNIQUE INDEX idx_artifact_aliases_scheme_ref ON artifact_aliases(scheme, normalized_ref);
CREATE INDEX idx_artifact_aliases_status ON artifact_aliases(resolution_status, scheme);
CREATE INDEX idx_artifact_blob_custody ON artifact_blob(custody_mode, availability);
CREATE INDEX idx_artifact_blob_provider ON artifact_blob(provider_id) WHERE provider_id IS NOT NULL;
CREATE INDEX idx_artifact_blob_role ON artifact_blob(role) WHERE role IS NOT NULL;
CREATE INDEX idx_artifact_drafts_base ON artifact_drafts(base_version_id) WHERE base_version_id IS NOT NULL;
CREATE UNIQUE INDEX idx_artifact_drafts_legacy_series ON artifact_drafts(series_id) WHERE series_id IS NOT NULL;
CREATE INDEX idx_artifact_drafts_version ON artifact_drafts(version_id);
CREATE INDEX idx_artifact_links_artifact ON artifact_links(artifact_id, link_type) WHERE artifact_id IS NOT NULL;
CREATE INDEX idx_artifact_links_blob ON artifact_links(blob_id, link_type);
CREATE INDEX idx_artifact_links_entity ON artifact_links(entity_type, entity_id);
CREATE INDEX idx_artifact_links_fallback_version ON artifact_links(fallback_version_id) WHERE fallback_version_id IS NOT NULL;
CREATE INDEX idx_artifact_links_kind ON artifact_links(link_kind);
CREATE INDEX idx_artifact_links_legacy_blob ON artifact_links(legacy_blob_id) WHERE legacy_blob_id IS NOT NULL;
CREATE INDEX idx_artifact_links_provider ON artifact_links(provider_id) WHERE provider_id IS NOT NULL;
CREATE INDEX idx_artifact_links_repo ON artifact_links(repo_id) WHERE repo_id IS NOT NULL;
CREATE INDEX idx_artifact_links_role ON artifact_links(role) WHERE role IS NOT NULL;
