CREATE TRIGGER trg_work_units_assigned_session_insert_normalize AFTER INSERT ON work_units WHEN NEW.assigned_session_id IS NOT NULL AND trim(NEW.assigned_session_id) = '' BEGIN UPDATE work_units SET assigned_session_id = NULL WHERE id = NEW.id; END;
CREATE TRIGGER trg_work_units_assigned_session_update_normalize AFTER UPDATE OF assigned_session_id ON work_units WHEN NEW.assigned_session_id IS NOT NULL AND trim(NEW.assigned_session_id) = '' BEGIN UPDATE work_units SET assigned_session_id = NULL WHERE id = NEW.id; END;
CREATE TABLE operational_incidents ( id TEXT PRIMARY KEY, executor TEXT NOT NULL, task TEXT NOT NULL, condition TEXT NOT NULL CHECK(condition IN ( 'failed_permanent', 'timeout', 'circuit_open', 'publish_stale', 'publish_quarantined', 'containment_blocked' )), first_seen INTEGER NOT NULL, observation_state TEXT NOT NULL CHECK(observation_state IN ('active','recovered')), attention_state TEXT NOT NULL DEFAULT 'unacknowledged' CHECK(attention_state IN ('unacknowledged','acknowledged')), remediation_state TEXT NOT NULL DEFAULT 'none' CHECK(remediation_state IN ( 'none', 'triaging', 'fix_prepared', 'awaiting_auth', 'auth_expired', 'awaiting_deploy', 'awaiting_verification', 'complete' )), latest_event_seq INTEGER NOT NULL CHECK(latest_event_seq IN (1,2)), latest_observed_at INTEGER NOT NULL, latest_event_id TEXT NOT NULL, latest_telemetry_json TEXT NOT NULL CHECK(json_valid(latest_telemetry_json)), latest_telemetry_sha256 TEXT NOT NULL CHECK(length(latest_telemetry_sha256) = 64), provenance TEXT NOT NULL DEFAULT 'executor_asserted_unverified' CHECK(provenance = 'executor_asserted_unverified'), posted_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, recovered_at INTEGER, recovery_run_id TEXT, acknowledged_at INTEGER, acknowledged_by_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, resolved_at INTEGER, resolution_kind TEXT CHECK(resolution_kind IS NULL OR resolution_kind IN ('successful_run','operator_closure')), operator_closed_at INTEGER, operator_closed_by_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(executor, task, condition, first_seen), CHECK( (observation_state = 'active' AND recovered_at IS NULL AND recovery_run_id IS NULL) OR (observation_state = 'recovered' AND recovered_at IS NOT NULL AND recovery_run_id IS NOT NULL) ), CHECK( (attention_state = 'unacknowledged' AND acknowledged_at IS NULL AND acknowledged_by_user_id IS NULL) OR (attention_state = 'acknowledged' AND acknowledged_at IS NOT NULL AND acknowledged_by_user_id IS NOT NULL) ), CHECK( (resolution_kind IS NULL AND resolved_at IS NULL) OR (resolution_kind IS NOT NULL AND resolved_at IS NOT NULL) ), CHECK( resolution_kind != 'successful_run' OR observation_state = 'recovered' ), CHECK( resolution_kind != 'operator_closure' OR (operator_closed_at IS NOT NULL AND operator_closed_by_user_id IS NOT NULL) ), CHECK( (resolved_at IS NULL AND remediation_state != 'complete') OR (resolved_at IS NOT NULL AND remediation_state = 'complete') ) );
CREATE INDEX idx_operational_incidents_queue ON operational_incidents( resolved_at, observation_state, attention_state, first_seen DESC, id );
CREATE INDEX idx_operational_incidents_task_history ON operational_incidents(executor, task, condition, first_seen DESC);
CREATE INDEX idx_operational_incidents_badge ON operational_incidents(attention_state, first_seen DESC) WHERE resolved_at IS NULL AND observation_state = 'active' AND attention_state = 'unacknowledged';
CREATE TABLE operational_incident_observation_events ( id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES operational_incidents(id) ON DELETE RESTRICT, source_event_id TEXT NOT NULL UNIQUE, event_seq INTEGER NOT NULL CHECK(event_seq IN (1,2)), observation_state TEXT NOT NULL CHECK(observation_state IN ('active','recovered')), observed_at INTEGER NOT NULL, inventory_digest TEXT NOT NULL CHECK(length(inventory_digest) = 64), telemetry_json TEXT NOT NULL CHECK(json_valid(telemetry_json)), telemetry_sha256 TEXT NOT NULL CHECK(length(telemetry_sha256) = 64), posted_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, received_at INTEGER NOT NULL, applied INTEGER NOT NULL CHECK(applied IN (0,1)), ignored_reason TEXT CHECK(ignored_reason IS NULL OR ignored_reason IN ('stale_sequence')), UNIQUE(incident_id, event_seq), CHECK( (event_seq = 1 AND observation_state = 'active') OR (event_seq = 2 AND observation_state = 'recovered') ), CHECK( (applied = 1 AND ignored_reason IS NULL) OR (applied = 0 AND ignored_reason IS NOT NULL) ) );
CREATE INDEX idx_operational_incident_observations_incident ON operational_incident_observation_events(incident_id, event_seq);
CREATE INDEX idx_operational_incident_observations_received ON operational_incident_observation_events(received_at DESC, id);
CREATE TABLE operational_incident_workflow_events ( id TEXT PRIMARY KEY, incident_id TEXT NOT NULL REFERENCES operational_incidents(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK(kind IN ( 'attention_acknowledged', 'operator_closed', 'prepare_fix_confirmed', 'dispatch_failed', 'remediation_transition' )), authority TEXT NOT NULL CHECK(authority IN ('user','server')), actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, from_attention_state TEXT CHECK(from_attention_state IS NULL OR from_attention_state IN ('unacknowledged','acknowledged')), to_attention_state TEXT CHECK(to_attention_state IS NULL OR to_attention_state IN ('unacknowledged','acknowledged')), from_remediation_state TEXT CHECK(from_remediation_state IS NULL OR from_remediation_state IN ( 'none','triaging','fix_prepared','awaiting_auth','auth_expired', 'awaiting_deploy','awaiting_verification','complete' )), to_remediation_state TEXT CHECK(to_remediation_state IS NULL OR to_remediation_state IN ( 'none','triaging','fix_prepared','awaiting_auth','auth_expired', 'awaiting_deploy','awaiting_verification','complete' )), agent_dispatch_event_id TEXT REFERENCES agent_dispatch_events(id) ON DELETE RESTRICT, auth_request_id TEXT, deploy_ref TEXT, verification_run_id TEXT, reason TEXT, metadata_json TEXT CHECK(metadata_json IS NULL OR json_valid(metadata_json)), created_at INTEGER NOT NULL, CHECK(authority != 'user' OR actor_user_id IS NOT NULL) );
CREATE INDEX idx_operational_incident_workflow_incident ON operational_incident_workflow_events(incident_id, created_at, id);
CREATE INDEX idx_operational_incident_workflow_dispatch ON operational_incident_workflow_events(agent_dispatch_event_id) WHERE agent_dispatch_event_id IS NOT NULL;
CREATE INDEX idx_operational_incident_workflow_auth ON operational_incident_workflow_events(auth_request_id) WHERE auth_request_id IS NOT NULL;
CREATE TABLE task_inventory_generations ( id TEXT PRIMARY KEY, digest TEXT NOT NULL, schema_id TEXT NOT NULL, executor_name TEXT NOT NULL, executor_version TEXT NOT NULL, capabilities_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(capabilities_json) AND json_type(capabilities_json)='array'), observed_at INTEGER NOT NULL, task_count INTEGER NOT NULL DEFAULT 0, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), posted_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, UNIQUE(executor_name, digest) );
CREATE INDEX idx_task_inventory_generations_executor ON task_inventory_generations(executor_name, observed_at DESC, created_at DESC);
CREATE INDEX idx_task_inventory_generations_received ON task_inventory_generations(created_at DESC);
CREATE TABLE task_command_requests ( id TEXT PRIMARY KEY, schema_id TEXT NOT NULL CHECK(schema_id IN ('task-command@1','task-command@2')), request_key TEXT NOT NULL CHECK(trim(request_key) != ''), request_digest TEXT NOT NULL CHECK(length(request_digest) = 64 AND request_digest NOT GLOB '*[^0-9a-f]*'), executor_name TEXT NOT NULL CHECK(trim(executor_name) != ''), task_id TEXT NOT NULL CHECK(trim(task_id) != ''), verb TEXT NOT NULL CHECK(verb IN ('disable','dry_run','enable')), payload_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(payload_json) AND json_type(payload_json) = 'object' AND ( (schema_id = 'task-command@1' AND verb = 'disable' AND payload_json = '{}') OR (schema_id = 'task-command@2' AND ( (verb = 'disable' AND payload_json = '{}') OR (verb IN ('dry_run','enable') AND json_type(payload_json, '$.execution_hash') = 'text' AND length(json_extract(payload_json, '$.execution_hash')) = 64 AND json_extract(payload_json, '$.execution_hash') NOT GLOB '*[^0-9a-f]*' AND payload_json = '{"execution_hash":"' || json_extract(payload_json, '$.execution_hash') || '"}') )) )), requested_by_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, requested_at INTEGER NOT NULL, UNIQUE(requested_by_user_id, request_key) );
CREATE INDEX idx_task_command_requests_target ON task_command_requests(executor_name, task_id, requested_at DESC);
CREATE TABLE task_command_events ( id TEXT PRIMARY KEY, command_id TEXT NOT NULL REFERENCES task_command_requests(id) ON DELETE RESTRICT, schema_id TEXT NOT NULL CHECK(schema_id IN ('task-command-event@1','task-command-event@2')), event_ordinal INTEGER NOT NULL CHECK(event_ordinal BETWEEN 0 AND 8), event_digest TEXT NOT NULL CHECK(length(event_digest) = 64 AND event_digest NOT GLOB '*[^0-9a-f]*'), event_type TEXT NOT NULL CHECK(event_type IN ( 'accepted','started','progress','applied','rejected','cancelled' )), payload_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(payload_json) AND json_type(payload_json) = 'object'), no_op INTEGER CHECK(no_op IS NULL OR no_op IN (0,1)), rejection_reason TEXT CHECK(rejection_reason IS NULL OR rejection_reason IN ( 'unknown_task','unsupported_verb','invalid_payload','stale_target', 'busy','missing_receipt','stale_receipt','policy_refused', 'dry_run_failed','unknown' )), actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, UNIQUE(command_id, event_ordinal), UNIQUE(command_id, event_digest), CHECK ( (event_type = 'accepted' AND event_ordinal = 0) OR (event_type = 'started' AND event_ordinal = 1) OR (event_type = 'progress' AND event_ordinal BETWEEN 2 AND 7) OR (event_type IN ('applied','rejected','cancelled') AND event_ordinal = 8) ), CHECK (schema_id = 'task-command-event@2' OR event_type IN ('accepted','applied','rejected','cancelled')), CHECK ( (event_type IN ('accepted','cancelled') AND payload_json = '{}' AND no_op IS NULL AND rejection_reason IS NULL) OR (event_type IN ('started','progress') AND no_op IS NULL AND rejection_reason IS NULL) OR (event_type = 'applied' AND rejection_reason IS NULL) OR (event_type = 'rejected' AND no_op IS NULL AND rejection_reason IS NOT NULL) ) );
CREATE UNIQUE INDEX uq_task_command_events_accepted ON task_command_events(command_id) WHERE event_type = 'accepted';
CREATE UNIQUE INDEX uq_task_command_events_started ON task_command_events(command_id) WHERE event_type = 'started';
CREATE UNIQUE INDEX uq_task_command_events_terminal ON task_command_events(command_id) WHERE event_type IN ('applied','rejected','cancelled');
CREATE INDEX idx_task_command_events_command ON task_command_events(command_id, event_ordinal);
CREATE TABLE briefings ( id TEXT PRIMARY KEY, briefing_key TEXT NOT NULL UNIQUE CHECK(trim(briefing_key) != ''), title TEXT NOT NULL CHECK(trim(title) != ''), description TEXT CHECK(description IS NULL OR (trim(description) != '' AND length(description) <= 1000)), latest_round_id TEXT, round_count INTEGER NOT NULL DEFAULT 0 CHECK(round_count >= 0), archived_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE briefing_members ( briefing_id TEXT NOT NULL REFERENCES briefings(id) ON DELETE RESTRICT, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, PRIMARY KEY(briefing_id, user_id) );
CREATE TABLE briefing_rounds ( id TEXT PRIMARY KEY, briefing_id TEXT NOT NULL REFERENCES briefings(id) ON DELETE RESTRICT, ordinal INTEGER NOT NULL CHECK(ordinal > 0), artifact_version_id TEXT NOT NULL REFERENCES artifact_version(id) ON DELETE RESTRICT, comparison_base_artifact_version_id TEXT REFERENCES artifact_version(id) ON DELETE RESTRICT, previous_round_id TEXT REFERENCES briefing_rounds(id) ON DELETE RESTRICT, profile TEXT NOT NULL CHECK(profile IN ('mandible-briefing.v2','mandible-briefing.v3')), binding_digest TEXT NOT NULL CHECK(length(binding_digest) = 64), created_at INTEGER NOT NULL, UNIQUE(briefing_id, ordinal), UNIQUE(id, briefing_id), UNIQUE(id, briefing_id, artifact_version_id), CHECK(previous_round_id IS NULL OR previous_round_id != id), FOREIGN KEY(previous_round_id, briefing_id) REFERENCES briefing_rounds(id, briefing_id) ON DELETE RESTRICT );
CREATE INDEX idx_briefing_rounds_briefing ON briefing_rounds(briefing_id, ordinal DESC);
CREATE INDEX idx_briefing_rounds_artifact_version ON briefing_rounds(artifact_version_id);
CREATE INDEX idx_briefing_rounds_comparison_base ON briefing_rounds(comparison_base_artifact_version_id);
CREATE TABLE briefing_directive_definitions ( id TEXT PRIMARY KEY, artifact_version_id TEXT NOT NULL REFERENCES artifact_version(id) ON DELETE RESTRICT, directive_key TEXT NOT NULL CHECK(length(directive_key) BETWEEN 1 AND 128), definition_digest TEXT NOT NULL CHECK(length(definition_digest) = 64), response_type TEXT NOT NULL CHECK(response_type IN ('verdict','single_choice','multi_choice','short_text','long_text','rating','text_variant')), required INTEGER NOT NULL DEFAULT 0 CHECK(required IN (0,1)), prompt TEXT NOT NULL, options_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(options_json) AND json_type(options_json) = 'array'), variants_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(variants_json) AND json_type(variants_json) = 'array'), start_offset INTEGER NOT NULL CHECK(start_offset >= 0), end_offset INTEGER NOT NULL CHECK(end_offset > start_offset), body_start_offset INTEGER NOT NULL CHECK(body_start_offset >= start_offset), body_end_offset INTEGER NOT NULL CHECK(body_end_offset > body_start_offset AND body_end_offset <= end_offset), created_at INTEGER NOT NULL, UNIQUE(artifact_version_id, directive_key), UNIQUE(id, artifact_version_id, directive_key) );
CREATE TABLE briefing_directive_instances ( id TEXT PRIMARY KEY, round_id TEXT NOT NULL, briefing_id TEXT NOT NULL, artifact_version_id TEXT NOT NULL, definition_id TEXT NOT NULL, directive_key TEXT NOT NULL CHECK(length(directive_key) BETWEEN 1 AND 128), position INTEGER NOT NULL CHECK(position >= 0), created_at INTEGER NOT NULL, UNIQUE(round_id, directive_key), UNIQUE(round_id, position), UNIQUE(id, round_id), UNIQUE(id, round_id, briefing_id), FOREIGN KEY(round_id, briefing_id, artifact_version_id) REFERENCES briefing_rounds(id, briefing_id, artifact_version_id) ON DELETE RESTRICT, FOREIGN KEY(definition_id, artifact_version_id, directive_key) REFERENCES briefing_directive_definitions(id, artifact_version_id, directive_key) ON DELETE RESTRICT );
CREATE INDEX idx_briefing_directive_instances_definition ON briefing_directive_instances(definition_id);
CREATE TABLE briefing_runs ( id TEXT PRIMARY KEY, briefing_id TEXT NOT NULL REFERENCES briefings(id) ON DELETE RESTRICT, round_id TEXT REFERENCES briefing_rounds(id) ON DELETE RESTRICT, artifact_version_id TEXT REFERENCES artifact_version(id) ON DELETE RESTRICT, publisher_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, task_identity TEXT NOT NULL CHECK(trim(task_identity) != ''), run_id TEXT NOT NULL CHECK(trim(run_id) != ''), run_key TEXT NOT NULL CHECK(trim(run_key) != ''), request_digest TEXT NOT NULL CHECK(length(request_digest) = 64), evidence_series_ref TEXT NOT NULL CHECK(trim(evidence_series_ref) != ''), evidence_version INTEGER NOT NULL CHECK(evidence_version >= 0), evidence_digest TEXT NOT NULL CHECK(length(evidence_digest) = 64), source_health_json TEXT NOT NULL CHECK(json_valid(source_health_json) AND json_type(source_health_json) = 'object'), quiet INTEGER NOT NULL CHECK(quiet IN (0,1)), quiet_reason TEXT, received_at INTEGER NOT NULL, UNIQUE(publisher_user_id, task_identity, run_key), UNIQUE(id, round_id, briefing_id), FOREIGN KEY(round_id, briefing_id, artifact_version_id) REFERENCES briefing_rounds(id, briefing_id, artifact_version_id) ON DELETE RESTRICT, CHECK((quiet = 1 AND round_id IS NULL AND artifact_version_id IS NULL AND quiet_reason IS NOT NULL) OR (quiet = 0 AND round_id IS NOT NULL AND artifact_version_id IS NOT NULL AND quiet_reason IS NULL)) );
CREATE INDEX idx_briefing_runs_briefing ON briefing_runs(briefing_id, received_at DESC);
CREATE TABLE briefing_run_occurrences ( id TEXT PRIMARY KEY, run_id TEXT NOT NULL, round_id TEXT NOT NULL, briefing_id TEXT NOT NULL, directive_instance_id TEXT NOT NULL, directive_key TEXT NOT NULL CHECK(length(directive_key) BETWEEN 1 AND 128), evidence_digest TEXT NOT NULL CHECK(length(evidence_digest) = 64), occurred_at INTEGER NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json) = 'object'), UNIQUE(run_id, directive_key, evidence_digest, occurred_at), FOREIGN KEY(run_id, round_id, briefing_id) REFERENCES briefing_runs(id, round_id, briefing_id) ON DELETE RESTRICT, FOREIGN KEY(directive_instance_id, round_id, briefing_id) REFERENCES briefing_directive_instances(id, round_id, briefing_id) ON DELETE RESTRICT );
CREATE TABLE briefing_response_events ( id TEXT PRIMARY KEY, round_id TEXT NOT NULL, briefing_id TEXT NOT NULL, directive_instance_id TEXT NOT NULL, operation TEXT NOT NULL CHECK(operation IN ('set','retract')), value_json TEXT, retracts_event_id TEXT REFERENCES briefing_response_events(id) ON DELETE RESTRICT, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, UNIQUE(id, round_id, directive_instance_id, actor_user_id), FOREIGN KEY(round_id, briefing_id) REFERENCES briefing_rounds(id, briefing_id) ON DELETE RESTRICT, FOREIGN KEY(directive_instance_id, round_id, briefing_id) REFERENCES briefing_directive_instances(id, round_id, briefing_id) ON DELETE RESTRICT, FOREIGN KEY(briefing_id, actor_user_id) REFERENCES briefing_members(briefing_id, user_id) ON DELETE RESTRICT, FOREIGN KEY(retracts_event_id, round_id, directive_instance_id, actor_user_id) REFERENCES briefing_response_events(id, round_id, directive_instance_id, actor_user_id) ON DELETE RESTRICT, CHECK((operation = 'set' AND value_json IS NOT NULL AND json_valid(value_json) AND json_type(value_json) = 'object' AND retracts_event_id IS NULL) OR (operation = 'retract' AND value_json IS NULL AND retracts_event_id IS NOT NULL)) );
CREATE UNIQUE INDEX uq_briefing_response_retraction ON briefing_response_events(retracts_event_id) WHERE operation = 'retract';
CREATE TRIGGER trg_briefing_response_retraction_identity BEFORE INSERT ON briefing_response_events WHEN NEW.operation = 'retract' BEGIN SELECT CASE WHEN NOT EXISTS ( SELECT 1 FROM briefing_response_events target WHERE target.id = NEW.retracts_event_id AND target.operation = 'set' AND target.round_id = NEW.round_id AND target.directive_instance_id = NEW.directive_instance_id AND target.actor_user_id = NEW.actor_user_id ) THEN RAISE(ABORT, 'briefing response retraction target mismatch') END; END;
CREATE INDEX idx_briefing_response_events_round_actor ON briefing_response_events(round_id, actor_user_id, created_at DESC);
CREATE TABLE briefing_annotation_events ( id TEXT PRIMARY KEY, round_id TEXT NOT NULL, briefing_id TEXT NOT NULL, operation TEXT NOT NULL CHECK(operation IN ('set','retract')), annotation_kind TEXT CHECK(annotation_kind IS NULL OR annotation_kind IN ('comment','suggest_replacement')), start_offset INTEGER, end_offset INTEGER, quote TEXT, body TEXT, replacement_text TEXT, retracts_event_id TEXT REFERENCES briefing_annotation_events(id) ON DELETE RESTRICT, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, UNIQUE(id, round_id, actor_user_id), FOREIGN KEY(round_id, briefing_id) REFERENCES briefing_rounds(id, briefing_id) ON DELETE RESTRICT, FOREIGN KEY(briefing_id, actor_user_id) REFERENCES briefing_members(briefing_id, user_id) ON DELETE RESTRICT, FOREIGN KEY(retracts_event_id, round_id, actor_user_id) REFERENCES briefing_annotation_events(id, round_id, actor_user_id) ON DELETE RESTRICT, CHECK((operation = 'set' AND annotation_kind IS NOT NULL AND start_offset IS NOT NULL AND start_offset >= 0 AND end_offset IS NOT NULL AND end_offset > start_offset AND quote IS NOT NULL AND quote != '' AND retracts_event_id IS NULL) OR (operation = 'retract' AND annotation_kind IS NULL AND start_offset IS NULL AND end_offset IS NULL AND quote IS NULL AND body IS NULL AND replacement_text IS NULL AND retracts_event_id IS NOT NULL)), CHECK(operation != 'set' OR (annotation_kind = 'comment' AND body IS NOT NULL AND trim(body) != '' AND replacement_text IS NULL) OR (annotation_kind = 'suggest_replacement' AND replacement_text IS NOT NULL AND (body IS NULL OR trim(body) != ''))) );
CREATE UNIQUE INDEX uq_briefing_annotation_retraction ON briefing_annotation_events(retracts_event_id) WHERE operation = 'retract';
CREATE TRIGGER trg_briefing_annotation_retraction_identity BEFORE INSERT ON briefing_annotation_events WHEN NEW.operation = 'retract' BEGIN SELECT CASE WHEN NOT EXISTS ( SELECT 1 FROM briefing_annotation_events target WHERE target.id = NEW.retracts_event_id AND target.operation = 'set' AND target.round_id = NEW.round_id AND target.actor_user_id = NEW.actor_user_id ) THEN RAISE(ABORT, 'briefing annotation retraction target mismatch') END; END;
CREATE INDEX idx_briefing_annotation_events_round_actor ON briefing_annotation_events(round_id, actor_user_id, created_at DESC);
CREATE TABLE briefing_submissions ( id TEXT PRIMARY KEY, round_id TEXT NOT NULL, briefing_id TEXT NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal > 0), supersedes_submission_id TEXT REFERENCES briefing_submissions(id) ON DELETE RESTRICT, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, UNIQUE(round_id, ordinal), UNIQUE(id, round_id, actor_user_id), FOREIGN KEY(round_id, briefing_id) REFERENCES briefing_rounds(id, briefing_id) ON DELETE RESTRICT, FOREIGN KEY(briefing_id, actor_user_id) REFERENCES briefing_members(briefing_id, user_id) ON DELETE RESTRICT, FOREIGN KEY(supersedes_submission_id, round_id, actor_user_id) REFERENCES briefing_submissions(id, round_id, actor_user_id) ON DELETE RESTRICT );
CREATE UNIQUE INDEX uq_briefing_submission_superseded_once_actor ON briefing_submissions(supersedes_submission_id, actor_user_id) WHERE supersedes_submission_id IS NOT NULL;
CREATE INDEX idx_briefing_submissions_round_actor ON briefing_submissions(round_id, actor_user_id, ordinal DESC);
CREATE TABLE briefing_submission_answers ( submission_id TEXT NOT NULL, round_id TEXT NOT NULL, actor_user_id TEXT NOT NULL, directive_instance_id TEXT NOT NULL, response_event_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position >= 0), PRIMARY KEY(submission_id, directive_instance_id), UNIQUE(submission_id, response_event_id), FOREIGN KEY(submission_id, round_id, actor_user_id) REFERENCES briefing_submissions(id, round_id, actor_user_id) ON DELETE RESTRICT, FOREIGN KEY(response_event_id, round_id, directive_instance_id, actor_user_id) REFERENCES briefing_response_events(id, round_id, directive_instance_id, actor_user_id) ON DELETE RESTRICT );
CREATE TABLE briefing_submission_annotations ( submission_id TEXT NOT NULL, round_id TEXT NOT NULL, actor_user_id TEXT NOT NULL, annotation_event_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position >= 0), PRIMARY KEY(submission_id, annotation_event_id), FOREIGN KEY(submission_id, round_id, actor_user_id) REFERENCES briefing_submissions(id, round_id, actor_user_id) ON DELETE RESTRICT, FOREIGN KEY(annotation_event_id, round_id, actor_user_id) REFERENCES briefing_annotation_events(id, round_id, actor_user_id) ON DELETE RESTRICT );
CREATE TRIGGER trg_briefing_submission_answer_set_only BEFORE INSERT ON briefing_submission_answers BEGIN SELECT CASE WHEN NOT EXISTS ( SELECT 1 FROM briefing_response_events event WHERE event.id = NEW.response_event_id AND event.operation = 'set' AND event.round_id = NEW.round_id AND event.directive_instance_id = NEW.directive_instance_id AND event.actor_user_id = NEW.actor_user_id ) THEN RAISE(ABORT, 'briefing frozen answer must reference matching set event') END; END;
CREATE TRIGGER trg_briefing_submission_annotation_set_only BEFORE INSERT ON briefing_submission_annotations BEGIN SELECT CASE WHEN NOT EXISTS ( SELECT 1 FROM briefing_annotation_events event WHERE event.id = NEW.annotation_event_id AND event.operation = 'set' AND event.round_id = NEW.round_id AND event.actor_user_id = NEW.actor_user_id ) THEN RAISE(ABORT, 'briefing frozen annotation must reference matching set event') END; END;
CREATE TABLE briefing_legacy_audit ( id TEXT PRIMARY KEY, legacy_collection_id TEXT NOT NULL, disposition TEXT NOT NULL CHECK(disposition IN ('reconstructed','sealed_ambiguous')), reason TEXT NOT NULL, provenance_json TEXT NOT NULL CHECK(json_valid(provenance_json) AND json_type(provenance_json) = 'object'), created_at INTEGER NOT NULL );
CREATE TABLE briefing_legacy_custody ( id TEXT PRIMARY KEY, briefing_id TEXT NOT NULL REFERENCES briefings(id) ON DELETE RESTRICT, source_profile TEXT NOT NULL CHECK(source_profile = 'mandible-briefing.v1'), disposition TEXT NOT NULL CHECK(disposition IN ('sealed_verified','sealed_ambiguous')), reason TEXT NOT NULL, packet_json TEXT NOT NULL CHECK(json_valid(packet_json) AND json_type(packet_json) = 'object'), packet_digest TEXT NOT NULL CHECK(length(packet_digest) = 64), created_at INTEGER NOT NULL, UNIQUE(briefing_id, source_profile) );
CREATE TABLE briefing_bundles ( id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(trim(name) != ''), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE briefing_bundle_members ( bundle_id TEXT NOT NULL REFERENCES briefing_bundles(id) ON DELETE RESTRICT, briefing_id TEXT NOT NULL REFERENCES briefings(id) ON DELETE RESTRICT, layout_position INTEGER NOT NULL CHECK(layout_position >= 0), entry_kind TEXT NOT NULL CHECK(entry_kind IN ('briefing','subgroup')), subgroup_name TEXT, subgroup_position INTEGER NOT NULL CHECK(subgroup_position >= 0), created_at INTEGER NOT NULL, PRIMARY KEY(bundle_id, briefing_id), UNIQUE(bundle_id, layout_position, subgroup_position), CHECK((entry_kind = 'briefing' AND subgroup_name IS NULL AND subgroup_position = 0) OR (entry_kind = 'subgroup' AND subgroup_name IS NOT NULL AND trim(subgroup_name) != '')) );
CREATE INDEX idx_briefing_bundle_members_briefing ON briefing_bundle_members(briefing_id);
CREATE TABLE briefing_groups ( id TEXT PRIMARY KEY, name TEXT NOT NULL CHECK(trim(name) != ''), current_bundle_id TEXT REFERENCES briefing_bundles(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE UNIQUE INDEX idx_briefing_groups_current_bundle ON briefing_groups(current_bundle_id) WHERE current_bundle_id IS NOT NULL;
CREATE TABLE briefing_group_updates ( group_id TEXT NOT NULL REFERENCES briefing_groups(id) ON DELETE RESTRICT, bundle_id TEXT NOT NULL UNIQUE REFERENCES briefing_bundles(id) ON DELETE RESTRICT, position INTEGER NOT NULL CHECK(position >= 0), created_at INTEGER NOT NULL, PRIMARY KEY(group_id, bundle_id), UNIQUE(group_id, position) );
CREATE TABLE briefing_group_dispositions ( id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES briefing_groups(id) ON DELETE RESTRICT, kind TEXT NOT NULL CHECK(kind IN ('promoted','dismissed')), prior_base_bundle_id TEXT REFERENCES briefing_bundles(id) ON DELETE RESTRICT, proposal_bundle_id TEXT NOT NULL REFERENCES briefing_bundles(id) ON DELETE RESTRICT, resulting_base_bundle_id TEXT REFERENCES briefing_bundles(id) ON DELETE RESTRICT, auth_request_id TEXT REFERENCES auth_requests(id) ON DELETE RESTRICT, merge_head_sha TEXT, created_at INTEGER NOT NULL, CHECK((kind = 'promoted' AND resulting_base_bundle_id = proposal_bundle_id AND auth_request_id IS NOT NULL AND length(merge_head_sha) = 40) OR (kind = 'dismissed' AND resulting_base_bundle_id IS NULL)), UNIQUE(auth_request_id, group_id, proposal_bundle_id) );
CREATE INDEX idx_briefing_group_dispositions_group ON briefing_group_dispositions(group_id, created_at DESC, id DESC);
CREATE TABLE conversation_sources ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, provider TEXT NOT NULL CHECK(provider IN ('claude_code','codex','gemini')), native_session_id TEXT NOT NULL, parser_format TEXT NOT NULL, parser_version TEXT NOT NULL, normalization_version TEXT NOT NULL, redaction_epoch INTEGER NOT NULL DEFAULT 0 CHECK(redaction_epoch >= 0), availability TEXT NOT NULL DEFAULT 'unchecked' CHECK(availability IN ('available','missing','stale','unsupported','unchecked')), custody_state TEXT NOT NULL DEFAULT 'provider' CHECK(custody_state IN ('provider','requested','capturing','verified','mirroring','sealed','error')), current_version_id TEXT, unavailable_reason TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(conversation_id, provider) );
CREATE INDEX idx_conversation_sources_native_session ON conversation_sources(provider, native_session_id);
CREATE INDEX idx_conversation_sources_availability ON conversation_sources(availability, custody_state);
CREATE TABLE conversation_source_aliases ( id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES conversation_sources(id) ON DELETE CASCADE, root_kind TEXT NOT NULL CHECK(root_kind IN ('provider','managed_custody')), root_path TEXT NOT NULL, relative_path TEXT NOT NULL, path TEXT NOT NULL UNIQUE, alias_kind TEXT NOT NULL CHECK(alias_kind IN ('active','archive','provider','managed')), availability TEXT NOT NULL DEFAULT 'unchecked' CHECK(availability IN ('available','missing','stale','unsupported','unchecked')), first_seen_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL );
CREATE INDEX idx_conversation_source_aliases_source ON conversation_source_aliases(source_id, availability, last_seen_at DESC);
CREATE TABLE conversation_source_versions ( id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES conversation_sources(id) ON DELETE CASCADE, content_sha256 TEXT NOT NULL, byte_length INTEGER NOT NULL CHECK(byte_length >= 0), file_mtime_ms REAL, generation TEXT NOT NULL CHECK(generation IN ('sealed_sha256','legacy_hash')), parser_format TEXT NOT NULL, parser_version TEXT NOT NULL, normalization_version TEXT NOT NULL, redaction_epoch INTEGER NOT NULL DEFAULT 0 CHECK(redaction_epoch >= 0), availability TEXT NOT NULL DEFAULT 'unchecked' CHECK(availability IN ('available','missing','stale','unsupported','unchecked')), custody_state TEXT NOT NULL DEFAULT 'provider' CHECK(custody_state IN ('provider','requested','capturing','verified','mirroring','sealed','error')), custody_ref TEXT, capture_consistency TEXT, verification_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(verification_json)), created_at INTEGER NOT NULL, filesystem_device TEXT, filesystem_inode TEXT, filesystem_ctime_ns TEXT, UNIQUE(source_id, content_sha256) );
CREATE INDEX idx_conversation_source_versions_source ON conversation_source_versions(source_id, created_at DESC);
CREATE INDEX idx_conversation_source_versions_custody ON conversation_source_versions(custody_state, availability);
CREATE TABLE conversation_normalization_checkpoints ( id TEXT PRIMARY KEY, source_version_id TEXT NOT NULL REFERENCES conversation_source_versions(id) ON DELETE CASCADE, record_ordinal INTEGER NOT NULL, prefix_offset INTEGER NOT NULL CHECK(prefix_offset >= 0), parser_format TEXT NOT NULL, parser_version TEXT NOT NULL, normalization_version TEXT NOT NULL, redaction_epoch INTEGER NOT NULL DEFAULT 0 CHECK(redaction_epoch >= 0), state_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(state_json)), created_at INTEGER NOT NULL, UNIQUE(source_version_id, record_ordinal, parser_version, normalization_version, redaction_epoch) );
CREATE TABLE conversation_structural_blocks ( id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, source_version_id TEXT REFERENCES conversation_source_versions(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'current' CHECK(status IN ('current','retired')), provider_key TEXT NOT NULL, position INTEGER NOT NULL CHECK(position >= 0), type TEXT NOT NULL, role TEXT NOT NULL, timestamp TEXT, parent_block_id TEXT REFERENCES conversation_structural_blocks(id) ON DELETE SET NULL, dag_uuid TEXT, dag_parent_uuid TEXT, record_offset INTEGER CHECK(record_offset IS NULL OR record_offset >= 0), record_length INTEGER CHECK(record_length IS NULL OR record_length >= 0), record_hash TEXT, record_ordinal INTEGER, sub_block_ordinal INTEGER NOT NULL DEFAULT 0 CHECK(sub_block_ordinal >= 0), normalization_checkpoint_id TEXT REFERENCES conversation_normalization_checkpoints(id) ON DELETE SET NULL, parser_format TEXT NOT NULL, parser_version TEXT NOT NULL, normalization_version TEXT NOT NULL, redaction_epoch INTEGER NOT NULL DEFAULT 0 CHECK(redaction_epoch >= 0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(conversation_id, provider_key) );
CREATE UNIQUE INDEX idx_conversation_structural_blocks_current_position ON conversation_structural_blocks(conversation_id, position) WHERE status = 'current';
CREATE INDEX idx_conversation_structural_blocks_version ON conversation_structural_blocks(source_version_id, record_offset);
CREATE INDEX idx_conversation_structural_blocks_parent ON conversation_structural_blocks(parent_block_id) WHERE parent_block_id IS NOT NULL;
CREATE TABLE conversation_block_aliases ( alias TEXT PRIMARY KEY, block_id TEXT NOT NULL REFERENCES conversation_structural_blocks(id) ON DELETE CASCADE, alias_kind TEXT NOT NULL CHECK(alias_kind IN ('legacy','provider','external')), created_at INTEGER NOT NULL );
CREATE INDEX idx_conversation_block_aliases_block ON conversation_block_aliases(block_id);
CREATE TABLE delegated_signing_runtime_bindings ( lease_id TEXT PRIMARY KEY REFERENCES delegated_signing_leases(id) ON DELETE CASCADE, agent_pid INTEGER NOT NULL CHECK(agent_pid > 0), agent_uid INTEGER NOT NULL CHECK(agent_uid >= 0), agent_process_start TEXT NOT NULL CHECK(trim(agent_process_start) != ''), agent_executable TEXT NOT NULL CHECK(trim(agent_executable) != ''), socket_path TEXT NOT NULL CHECK(trim(socket_path) != ''), socket_dev TEXT NOT NULL CHECK(trim(socket_dev) != ''), socket_ino TEXT NOT NULL CHECK(trim(socket_ino) != ''), socket_uid INTEGER NOT NULL CHECK(socket_uid >= 0), socket_mode INTEGER NOT NULL CHECK(socket_mode >= 0), credential_fingerprint TEXT NOT NULL CHECK(trim(credential_fingerprint) != ''), public_key_path TEXT NOT NULL CHECK(trim(public_key_path) != ''), issued_runtime_epoch TEXT NOT NULL CHECK(trim(issued_runtime_epoch) != ''), owner_runtime_epoch TEXT NOT NULL CHECK(trim(owner_runtime_epoch) != ''), owner_pid INTEGER NOT NULL CHECK(owner_pid > 0), owner_uid INTEGER NOT NULL CHECK(owner_uid >= 0), owner_process_start TEXT NOT NULL CHECK(trim(owner_process_start) != ''), owner_executable TEXT NOT NULL CHECK(trim(owner_executable) != ''), attached_at INTEGER NOT NULL, last_validated_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('available','draining','retired','lost')), retired_at INTEGER, retired_reason TEXT, CHECK((state IN ('available','draining') AND retired_at IS NULL) OR (state IN ('retired','lost') AND retired_at IS NOT NULL)) );
CREATE INDEX idx_delegated_signing_runtime_owner ON delegated_signing_runtime_bindings(owner_runtime_epoch, state);
CREATE TABLE auth_clearances ( id TEXT PRIMARY KEY, issuer_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, grantee_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, grantee_credential_id TEXT NOT NULL REFERENCES user_credentials(id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES ledger_projects(id) ON DELETE RESTRICT, base_branch TEXT NOT NULL CHECK(trim(base_branch) != ''), issue_id TEXT REFERENCES ledger_issues(id) ON DELETE RESTRICT, head_branch TEXT, action TEXT NOT NULL CHECK(action = 'merge'), issued_at INTEGER NOT NULL, expires_at INTEGER NOT NULL CHECK(expires_at > issued_at), max_uses INTEGER NOT NULL CHECK(max_uses BETWEEN 1 AND 100), revoked_at INTEGER, revoked_by_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, runtime_epoch TEXT NOT NULL CHECK(trim(runtime_epoch) != ''), signing_lease_id TEXT NOT NULL REFERENCES delegated_signing_leases(id) ON DELETE RESTRICT, created_from_request_id TEXT, CHECK(issue_id IS NOT NULL OR (head_branch IS NOT NULL AND trim(head_branch) != '')), CHECK((revoked_at IS NULL AND revoked_by_user_id IS NULL) OR (revoked_at IS NOT NULL AND revoked_by_user_id IS NOT NULL)) );
CREATE INDEX idx_auth_clearances_match ON auth_clearances(project_id, base_branch, grantee_user_id, expires_at);
CREATE INDEX idx_auth_clearances_issue ON auth_clearances(issue_id) WHERE issue_id IS NOT NULL;
CREATE INDEX idx_auth_clearances_head ON auth_clearances(head_branch) WHERE head_branch IS NOT NULL;
CREATE TABLE auth_clearance_uses ( id TEXT PRIMARY KEY, clearance_id TEXT NOT NULL REFERENCES auth_clearances(id) ON DELETE RESTRICT, auth_request_id TEXT NOT NULL UNIQUE, use_ordinal INTEGER NOT NULL CHECK(use_ordinal >= 1), evidence_id TEXT NOT NULL UNIQUE REFERENCES attribution_evidence(id) ON DELETE RESTRICT, requester_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, requester_evidence_method TEXT NOT NULL CHECK(requester_evidence_method IN ('api_token','credential_signature')), requester_credential_id TEXT NOT NULL REFERENCES user_credentials(id) ON DELETE RESTRICT, signing_lease_id TEXT NOT NULL REFERENCES delegated_signing_leases(id) ON DELETE RESTRICT, request_snapshot_json TEXT NOT NULL CHECK(json_valid(request_snapshot_json) AND json_type(request_snapshot_json) = 'object'), request_snapshot_digest TEXT NOT NULL CHECK(length(request_snapshot_digest) = 64 AND request_snapshot_digest NOT GLOB '*[^0-9a-f]*'), consumed_at INTEGER NOT NULL, UNIQUE(clearance_id, use_ordinal) );
CREATE TRIGGER auth_clearances_scope_immutable BEFORE UPDATE OF issuer_user_id, grantee_user_id, grantee_credential_id, project_id, base_branch, issue_id, head_branch, action, issued_at, expires_at, max_uses, runtime_epoch, signing_lease_id, created_from_request_id ON auth_clearances BEGIN SELECT RAISE(ABORT, 'auth clearance scope is immutable'); END;
CREATE TRIGGER auth_clearances_revocation_immutable BEFORE UPDATE OF revoked_at, revoked_by_user_id ON auth_clearances WHEN OLD.revoked_at IS NOT NULL OR NEW.revoked_at IS NULL OR NEW.revoked_by_user_id IS NULL BEGIN SELECT RAISE(ABORT, 'auth clearance revocation is immutable'); END;
CREATE TRIGGER auth_clearances_delete_forbidden BEFORE DELETE ON auth_clearances BEGIN SELECT RAISE(ABORT, 'auth clearance audit is append-only'); END;
CREATE TRIGGER auth_clearance_uses_immutable BEFORE UPDATE ON auth_clearance_uses BEGIN SELECT RAISE(ABORT, 'auth clearance use evidence is immutable'); END;
CREATE TRIGGER auth_clearance_uses_delete_forbidden BEFORE DELETE ON auth_clearance_uses BEGIN SELECT RAISE(ABORT, 'auth clearance use evidence is append-only'); END;
CREATE TRIGGER auth_requests_clearance_review_frozen BEFORE UPDATE OF requested_by_user_id, requester_evidence_method, requester_credential_id, type, command, cwd, repo, base_branch, head_branch, merge_head_sha, issue_references, issue_closures, issues, execution_mode ON auth_requests WHEN OLD.clearance_use_id IS NOT NULL BEGIN SELECT RAISE(ABORT, 'clearance-reviewed auth request fields are frozen'); END;
CREATE TABLE space_items ( id TEXT NOT NULL, space_id TEXT NOT NULL REFERENCES spaces(id) ON DELETE CASCADE, ref_type TEXT NOT NULL CHECK(ref_type IN ('issue','comment','artifact','external_ref','space')), ref_id TEXT NOT NULL CHECK(ref_id != ''), ref_uri TEXT, title TEXT, metadata_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata_json) AND json_type(metadata_json)='object'), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(id), UNIQUE(space_id,id), UNIQUE(space_id,ref_type,ref_id), CHECK(ref_type != 'external_ref' OR ref_uri IS NOT NULL) );
CREATE INDEX idx_space_items_lookup ON space_items(space_id, ref_type, ref_id);
CREATE INDEX idx_space_items_by_ref ON space_items(ref_type, ref_id, space_id);
CREATE TABLE agent_dispatch_events ( id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL CHECK(subject_kind IN ('issue','incident')), issue_id TEXT, incident_id TEXT REFERENCES operational_incidents(id) ON DELETE RESTRICT, incident_telemetry_sha256 TEXT CHECK(incident_telemetry_sha256 IS NULL OR length(incident_telemetry_sha256) = 64), actor_user_id TEXT REFERENCES users(id) ON DELETE RESTRICT, provider TEXT NOT NULL DEFAULT 'claude', instruction TEXT NOT NULL, cwd TEXT NOT NULL, prompt_path TEXT, prompt_sha256 TEXT, status TEXT NOT NULL CHECK(status IN ('dispatching','dispatched','failed')), session_handle TEXT, session_id TEXT, attach_command TEXT, error TEXT, created_at INTEGER NOT NULL, settled_at INTEGER, CHECK((subject_kind = 'issue' AND issue_id IS NOT NULL AND incident_id IS NULL) OR (subject_kind = 'incident' AND incident_id IS NOT NULL AND incident_telemetry_sha256 IS NOT NULL AND issue_id IS NULL)) );
CREATE INDEX idx_agent_dispatch_events_issue ON agent_dispatch_events(issue_id, created_at DESC);
CREATE INDEX idx_agent_dispatch_events_incident ON agent_dispatch_events(incident_id, created_at DESC);
