INSERT INTO auth_hooks (id, repo_pattern, auth_type, command, label, enabled, builtin, position, created_at, updated_at, required) VALUES ('builtin-dotfiles-agent-instructions', '.dotfiles', 'merge', 'if [[ -x bin/agent-instruction-symlink-doctor ]]; then bash bin/agent-instruction-symlink-doctor; elif [[ -x bin/compile-agent-instructions ]]; then bash bin/compile-agent-instructions; else echo "dotfiles agent instruction hook missing repair script" >&2; exit 1; fi', 'Compile agent instructions and repair home symlinks', 1, 1, 0, 1787638522641, 1787638522641, 1);
INSERT INTO auth_hooks (id, repo_pattern, auth_type, command, label, enabled, builtin, position, created_at, updated_at, required) VALUES ('builtin-dotfiles-agent-instructions-nodot', 'dotfiles', 'merge', 'if [[ -x bin/agent-instruction-symlink-doctor ]]; then bash bin/agent-instruction-symlink-doctor; elif [[ -x bin/compile-agent-instructions ]]; then bash bin/compile-agent-instructions; else echo "dotfiles agent instruction hook missing repair script" >&2; exit 1; fi', 'Compile agent instructions and repair home symlinks', 1, 1, 0, 1787638522641, 1787638522641, 1);
INSERT INTO auth_hooks (id, repo_pattern, auth_type, command, label, enabled, builtin, position, created_at, updated_at, required) VALUES ('builtin-dotfiles-agent-schedule-deploy', '.dotfiles', 'merge', 'set -o pipefail
base=$(git rev-parse --verify -q HEAD^1 || git rev-parse --verify -q HEAD~1)
if [ -z "$base" ]; then echo "agent-schedule deploy hook: cannot resolve the merge parent" >&2; exit 1; fi
if [ -z "$(git diff --name-only "$base" HEAD -- agents/)" ]; then echo "no agents/ changes in this merge; skipping agent-schedule deploy"; exit 0; fi
sched=""
for candidate in "$HOME/.local/bin/agent-schedule" "$HOME/.dotfiles/bin/agent-schedule"; do
  if [ -x "$candidate" ]; then sched="$candidate"; break; fi
done
if [ -z "$sched" ]; then echo "agent-schedule deploy hook: agent-schedule executable not found" >&2; exit 1; fi
"$sched" deploy', 'Deploy the agent-schedule bundle after an agents/ merge', 1, 1, 10, 1787638522641, 1787638522641, 1);
INSERT INTO auth_hooks (id, repo_pattern, auth_type, command, label, enabled, builtin, position, created_at, updated_at, required) VALUES ('builtin-dotfiles-agent-schedule-deploy-nodot', 'dotfiles', 'merge', 'set -o pipefail
base=$(git rev-parse --verify -q HEAD^1 || git rev-parse --verify -q HEAD~1)
if [ -z "$base" ]; then echo "agent-schedule deploy hook: cannot resolve the merge parent" >&2; exit 1; fi
if [ -z "$(git diff --name-only "$base" HEAD -- agents/)" ]; then echo "no agents/ changes in this merge; skipping agent-schedule deploy"; exit 0; fi
sched=""
for candidate in "$HOME/.local/bin/agent-schedule" "$HOME/.dotfiles/bin/agent-schedule"; do
  if [ -x "$candidate" ]; then sched="$candidate"; break; fi
done
if [ -z "$sched" ]; then echo "agent-schedule deploy hook: agent-schedule executable not found" >&2; exit 1; fi
"$sched" deploy', 'Deploy the agent-schedule bundle after an agents/ merge', 1, 1, 10, 1787638522641, 1787638522641, 1);
